    10→// Error categories
    11→export type ErrorCategory =
    12→	| "provider" // AI provider errors
    13→	| "parsing" // Response parsing failures
    14→	| "repository" // Git/repo access
    15→	| "file_system" // File operations
    16→	| "timeout" // Operation timeouts
    17→	| "internal"; // Unexpected errors
