    31→// Context Score types - New "Base + Setup Bonus - Issue Penalty" Algorithm
    32→export interface IContextScoreBreakdown {
    33→	// New algorithm components
    34→	baseScore: number; // Always 6.0 (supportive starting point)
    35→	setupBonus: {
    36→		agentsFilesBonus: number; // 0-2.0 based on number of AGENTS.md files
    37→		skillsBonus: number; // 0-0.75 based on skills count
    38→		linkedDocsBonus: number; // 0-0.75 based on linked docs count
    39→		total: number; // Sum of all setup bonuses (max 3.5)
    40→	};
    41→	issuePenalty: {
    42→		weightedIssueCount: number; // Raw weighted issue count before normalization
    43→		issueAllowance: number; // "Free" issues based on project size
    44→		excessIssues: number; // Issues beyond allowance
    45→		penalty: number; // Final penalty (0-3.0, soft cap)
    46→	};
    47→	context: {
    48→		projectSizeTier: "small" | "medium" | "large" | "enterprise";
    49→		totalLOC: number; // Lines of code from cloc
    50→		agentsFileCount: number;
    51→		skillsCount: number;
    52→		linkedDocsCount: number;
    53→		// Issue breakdown (3-level system: High 8-10, Medium 6-7, Low ≤5)
    54→		highIssues: number;
    55→		mediumIssues: number;
    56→		lowIssues: number;
    57→		errorCount: number;
    58→		suggestionCount: number;
    59→	};
    60→	// Legacy fields for backward compatibility
    61→	coveragePenalty?: number;
    62→	categoryDiversityPenalty?: number;
    63→	totalPenalty?: number;
    64→}
