    93→// Context file interface for AGENTS.md, CLAUDE.md, .claude/rules/*.md, copilot-instructions.md
    94→export interface IContextFile {
    95→	path: string; // Relative path from repository root
    96→	type: "agents" | "claude" | "copilot" | "rules"; // File type for categorization
    97→	content: string; // Raw file content
    98→	summary: string; // AI-generated 2-sentence summary
