   123→export interface Location {
   124→	file?: string;
   125→	start: number;
   126→	end: number;
   127→}
   128→
   129→export interface SnippetInfo {
   130→	content: string; // Full snippet with context lines
   131→	startLine: number; // First line number of snippet (1-indexed)
   132→	highlightStart: number; // Line number where highlight starts (1-indexed)
   133→	highlightEnd: number; // Line number where highlight ends (1-indexed)
   134→	file?: string; // File path for cross-file snippets
   135→}
