   137→// Common fields shared by both error and suggestion issues
   138→interface BaseIssue {
   139→	category: string;
   140→	problem?: string;
   141→	description?: string;
   142→	title?: string;
   143→	location: Location | Location[];
   144→	impact?: string; // Explanation text (why it matters)
   145→	fix?: string;
   146→	recommendation?: string;
   147→	suggestion?: string;
   148→	affectedFiles?: string[];
   149→	isMultiFile?: boolean;
   150→	context?: string;
   151→	quote?: string;
   152→	pattern?: string;
   153→	issue?: string;
   154→	snippet?: string; // Actual content at the location (extracted from file)
   155→	snippetInfo?: SnippetInfo; // Snippet with context and line number metadata
   156→	snippets?: SnippetInfo[]; // Multiple snippets for cross-file issues
   157→	snippetError?: string; // Reason why snippet is not available (e.g., "File not found", "Line exceeds file length")
   158→	isPhantomFile?: boolean; // Indicates this references a suggested file location that doesn't exist yet (e.g., subdirectory AGENTS.md)
   159→	evaluatorName?: string; // Name of the evaluator that found this issue
   160→	issueType: "error" | "suggestion"; // Whether this is an error (problem to fix) or suggestion (opportunity to improve)
   161→	validationWarnings?: string[]; // Warnings about potential false positives (e.g., hallucinated pronouns)
   162→}
   163→
   164→// Error issues have severity only
   165→export interface ErrorIssue extends BaseIssue {
   166→	issueType: "error";
   167→	severity: number; // 6-10 scale
   168→	impactLevel?: never; // Explicitly forbidden
   169→}
   170→
   171→// Suggestion issues have impactLevel only
   172→export interface SuggestionIssue extends BaseIssue {
   173→	issueType: "suggestion";
   174→	impactLevel: "High" | "Medium" | "Low"; // Impact level for suggestions
   175→	severity?: never; // Explicitly forbidden
   176→}
   177→
   178→// Union type for all issues
   179→export type Issue = ErrorIssue | SuggestionIssue;
