  1→/**
  2→ * Remediation prompt generator.
  3→ *
  4→ * Generates copy-paste-ready AI agent prompts from evaluation results:
  5→ * - Error fix prompt: instructs an agent to fix documentation issues
  6→ * - Suggestion enrich prompt: instructs an agent to add missing documentation
  7→ */
  8→
  9→export interface RemediationIssue {
 10→	evaluatorName: string;
 11→	category: string;
 12→	title?: string;
 13→	problem?: string;
 14→	description?: string;
 15→	severity?: number;
 16→	impactLevel?: string;
 17→	location: { file?: string; start: number; end: number };
 18→	snippet?: string;
 19→	fix?: string;
 20→	recommendation?: string;
 21→	isPhantomFile?: boolean;
 22→}
 23→
 24→export interface RemediationInput {
 25→	targetFileType: "AGENTS.md" | "CLAUDE.md";
 26→	contextFilePaths: string[];
 27→	errors: RemediationIssue[];
 28→	suggestions: RemediationIssue[];
 29→	technicalInventorySection: string;
 30→	projectSummary: {
 31→		languages?: string;
 32→		frameworks?: string;
 33→		architecture?: string;
 34→	};
 35→}
 36→
 37→export interface RemediationPrompts {
 38→	errorFixPrompt: string;
 39→	suggestionEnrichPrompt: string;
 40→	errorCount: number;
 41→	suggestionCount: number;
 42→}
 43→
 44→function formatIssueDescription(issue: RemediationIssue): string {
 45→	return issue.problem || issue.description || issue.title || "No description";
 46→}
 47→
 48→function formatIssueFix(issue: RemediationIssue): string {
 49→	return issue.fix || issue.recommendation || "Review and fix this issue";
 50→}
 51→
 52→function formatProjectLine(
 53→	summary: RemediationInput["projectSummary"],
 54→): string {
 55→	const parts: string[] = [];
 56→	if (summary.languages) parts.push(`Languages: ${summary.languages}`);
 57→	if (summary.frameworks) parts.push(`Frameworks: ${summary.frameworks}`);
 58→	if (summary.architecture) parts.push(`Architecture: ${summary.architecture}`);
 59→	return parts.length > 0 ? parts.join(" | ") : "Not identified";
 60→}
 61→
 62→function formatErrorIssueBlock(issue: RemediationIssue, index: number): string {
 63→	const lines: string[] = [];
 64→	lines.push(`### ${index + 1}. ${issue.evaluatorName}: ${issue.category}`);
 65→	lines.push(`**Severity**: ${issue.severity ?? "N/A"}/10`);
 66→
 67→	if (issue.location.file) {
 68→		lines.push(
 69→			`**File**: ${issue.location.file}, lines ${issue.location.start}-${issue.location.end}`,
 70→		);
 71→	}
 72→
 73→	lines.push(`**Problem**: ${formatIssueDescription(issue)}`);
 74→
 75→	if (issue.snippet) {
 76→		lines.push("**Current content**:");
 77→		lines.push(`> ${issue.snippet.split("\n").join("\n> ")}`);
 78→	}
 79→
 80→	lines.push(`**Fix**: ${formatIssueFix(issue)}`);
 81→
 82→	return lines.join("\n");
 83→}
 84→
 85→function formatSuggestionIssueBlock(
 86→	issue: RemediationIssue,
 87→	index: number,
 88→): string {
 89→	const lines: string[] = [];
 90→	lines.push(`### ${index + 1}. ${issue.evaluatorName}: ${issue.category}`);
 91→	lines.push(`**Impact**: ${issue.impactLevel ?? "N/A"}`);
 92→
 93→	if (issue.isPhantomFile && issue.location.file) {
 94→		lines.push(`**Action**: Create new file at \`${issue.location.file}\``);
 95→	} else if (issue.location.file) {
 96→		lines.push(
 97→			`**File**: ${issue.location.file}, lines ${issue.location.start}-${issue.location.end}`,
 98→		);
 99→	}
100→
101→	lines.push(`**Gap**: ${formatIssueDescription(issue)}`);
102→
103→	if (issue.snippet) {
104→		lines.push("**Current content**:");
105→		lines.push(`> ${issue.snippet.split("\n").join("\n> ")}`);
106→	}
107→
108→	lines.push(`**Recommendation**: ${formatIssueFix(issue)}`);
109→
110→	return lines.join("\n");
111→}
112→
113→function buildErrorFixPrompt(input: RemediationInput): string {
114→	if (input.errors.length === 0) {
115→		return "";
116→	}
117→
118→	// Sort by severity descending
119→	const sorted = [...input.errors].sort(
120→		(a, b) => (b.severity ?? 0) - (a.severity ?? 0),
121→	);
122→
123→	const contextFilesList = input.contextFilePaths
124→		.map((p) => `- ${p}`)
125→		.join("\n");
126→	const issueBlocks = sorted
127→		.map((issue, i) => formatErrorIssueBlock(issue, i))
128→		.join("\n\n");
129→
130→	return `# Fix Documentation Issues
131→
132→## Role
133→You are fixing documentation quality issues in ${input.targetFileType} files.
134→These files guide AI coding agents. Fixes must be precise and concise.
135→
136→## Context Files
137→${contextFilesList}
138→
139→${input.technicalInventorySection ? `## Technical Context\n${input.technicalInventorySection}\n` : ""}## Project
140→${formatProjectLine(input.projectSummary)}
141→
142→## Issues to Fix (${input.errors.length})
143→
144→${issueBlocks}
145→
146→## Instructions
147→1. Read the target files from disk before making changes
148→2. Use your own judgment to assess each issue: these were produced by an automated evaluator and some may be false positives or irrelevant given the actual file content. Skip any issue that is not a real problem after reading the file
149→3. Fix each remaining issue, highest severity first
150→4. Preserve all correct existing content
151→5. Keep changes minimal — only fix what's genuinely flagged
152→6. Do not add commentary, headers, or sections beyond what's needed
153→7. After making all changes, output a JSON summary:
154→\`\`\`json
155→{
156→  "actions": [
157→    { "issueIndex": 1, "status": "fixed", "file": "AGENTS.md", "summary": "Replaced vague setup instructions with exact commands" },
158→    { "issueIndex": 2, "status": "skipped", "summary": "Not a real issue after reading the file" }
159→  ]
160→}
161→\`\`\`
162→Use issue numbers from above. Status: "fixed" or "skipped". Keep summaries under 15 words.`;
163→}
164→
165→function buildSuggestionEnrichPrompt(input: RemediationInput): string {
166→	if (input.suggestions.length === 0) {
167→		return "";
168→	}
169→
170→	// Sort by impact level: High > Medium > Low
171→	const impactOrder: Record<string, number> = { High: 0, Medium: 1, Low: 2 };
172→	const sorted = [...input.suggestions].sort(
173→		(a, b) =>
174→			(impactOrder[a.impactLevel ?? "Low"] ?? 2) -
175→			(impactOrder[b.impactLevel ?? "Low"] ?? 2),
176→	);
177→
178→	const contextFilesList = input.contextFilePaths
179→		.map((p) => `- ${p}`)
180→		.join("\n");
181→	const issueBlocks = sorted
182→		.map((issue, i) => formatSuggestionIssueBlock(issue, i))
183→		.join("\n\n");
184→
185→	return `# Enrich Documentation
186→
187→## Role
188→You are enriching AI agent documentation in ${input.targetFileType} files.
189→These files guide AI coding agents. Additions must be accurate and concise.
190→
191→## Context Files
192→${contextFilesList}
193→
194→${input.technicalInventorySection ? `## Technical Context\n${input.technicalInventorySection}\n` : ""}## Project
195→${formatProjectLine(input.projectSummary)}
196→
197→## Documentation Gaps (${input.suggestions.length})
198→
199→${issueBlocks}
200→
201→## Instructions
202→1. Read the target files and scan the codebase before making changes
203→2. Use your own judgment to assess each gap: these were produced by an automated evaluator and some may be false positives or irrelevant given the actual codebase. Skip any suggestion that is not genuinely useful after reviewing the code
204→3. Address each remaining gap, highest impact first
205→4. Add concise, accurate documentation based on actual codebase analysis
206→5. When a gap specifies "Create new file at <path>", create that file with the recommended content
207→6. Preserve all correct existing content
208→7. Keep additions minimal — only add what's needed to close the gap
209→8. After making all changes, output a JSON summary:
210→\`\`\`json
211→{
212→  "actions": [
213→    { "issueIndex": 1, "status": "added", "file": "AGENTS.md", "summary": "Added testing patterns section with Jest conventions" },
214→    { "issueIndex": 2, "status": "skipped", "summary": "Already documented in existing section" }
215→  ]
216→}
217→\`\`\`
218→Use gap numbers from above. Status: "added" or "skipped". Keep summaries under 15 words.`;
219→}
220→
221→export function generateRemediationPrompts(
222→	input: RemediationInput,
223→): RemediationPrompts {
224→	return {
225→		errorFixPrompt: buildErrorFixPrompt(input),
226→		suggestionEnrichPrompt: buildSuggestionEnrichPrompt(input),
227→		errorCount: input.errors.length,
228→		suggestionCount: input.suggestions.length,
229→	};
230→}
