  1→// File Consistency Validator Module
  2→// Detects when AGENTS.md and CLAUDE.md coexist in the same directory with different content
  3→
  4→import {
  5→	findColocatedMdFiles,
  6→	getRelativePath,
  7→} from "@shared/file-system/file-finder";
  8→import type { Issue, Location } from "@shared/types/evaluation";
  9→import { createTwoFilesPatch } from "diff";
 10→import { readFile } from "fs/promises";
 11→
 12→/**
 13→ * Strip Packmind standards section from content
 14→ * Removes content between <!-- start: Packmind standards --> and <!-- end: Packmind standards --> tags
 15→ * including the tags themselves
 16→ */
 17→function stripPackmindStandards(content: string): string {
 18→	const startTag = "<!-- start: Packmind standards -->";
 19→	const endTag = "<!-- end: Packmind standards -->";
 20→
 21→	const startIndex = content.indexOf(startTag);
 22→	if (startIndex === -1) {
 23→		return content;
 24→	}
 25→
 26→	const endIndex = content.indexOf(endTag, startIndex);
 27→	if (endIndex === -1) {
 28→		return content; // No closing tag found, return original
 29→	}
 30→
 31→	// Remove the section including tags
 32→	const before = content.slice(0, startIndex);
 33→	const after = content.slice(endIndex + endTag.length);
 34→
 35→	return before + after;
 36→}
 37→
 38→/**
 39→ * Normalize trailing newlines in content.
 40→ * Ensures consistent trailing newline behavior to prevent false positives
 41→ * when files differ only in trailing whitespace at EOF.
 42→ *
 43→ * Behavior:
 44→ * - Multiple trailing newlines -> single newline ("content\n\n\n" -> "content\n")
 45→ * - Single trailing newline -> preserved ("content\n" -> "content\n")
 46→ * - No trailing newline -> adds one ("content" -> "content\n")
 47→ */
 48→function normalizeTrailingNewlines(content: string): string {
 49→	return content.replace(/\n*$/, "\n");
 50→}
 51→
 52→/**
 53→ * Options for file consistency validation
 54→ */
 55→export interface ConsistencyValidationOptions {
 56→	verbose?: boolean;
 57→	agentsFiles?: string[]; // Optional: pre-discovered paths (not directly used but for consistency)
 58→}
 59→
 60→/**
 61→ * Result of consistency validation
 62→ */
 63→export interface ConsistencyValidationResult {
 64→	issues: Issue[];
 65→	pairsChecked: number;
 66→	conflictsFound: number;
 67→}
 68→
 69→/**
 70→ * Validate file consistency for colocated AGENTS.md and CLAUDE.md files
 71→ * @param baseDir - Base directory to search in
 72→ * @param options - Validation options
 73→ * @returns Validation result with issues found
 74→ */
 75→export async function validateFileConsistency(
 76→	baseDir: string,
 77→	options: ConsistencyValidationOptions = {},
 78→): Promise<ConsistencyValidationResult> {
 79→	const { verbose = false } = options;
 80→
 81→	try {
 82→		// Find pairs of colocated files
 83→		const pairs = await findColocatedMdFiles(baseDir);
 84→
 85→		if (verbose) {
 86→			console.log(
 87→				`[FileConsistencyValidator] Found ${pairs.length} colocated AGENTS.md/CLAUDE.md pairs`,
 88→			);
 89→		}
 90→
 91→		const issues: Issue[] = [];
 92→		let conflictsFound = 0;
 93→
 94→		// Check each pair for consistency
 95→		for (const pair of pairs) {
 96→			try {
 97→				const [agentsContent, claudeContent] = await Promise.all([
 98→					readFile(pair.agentsPath, "utf-8"),
 99→					readFile(pair.claudePath, "utf-8"),
100→				]);
101→
102→				// Strip Packmind standards sections before comparison
103→				const agentsContentStripped = stripPackmindStandards(agentsContent);
104→				const claudeContentStripped = stripPackmindStandards(claudeContent);
105→
106→				// Normalize trailing newlines (ignore differences in empty lines at EOF)
107→				const agentsNormalized = normalizeTrailingNewlines(
108→					agentsContentStripped,
109→				);
110→				const claudeNormalized = normalizeTrailingNewlines(
111→					claudeContentStripped,
112→				);
113→
114→				// Byte-for-byte comparison (with Packmind sections excluded and trailing newlines normalized)
115→				if (agentsNormalized !== claudeNormalized) {
116→					conflictsFound++;
117→
118→					// Generate unified diff using NORMALIZED content
119→					const agentsRelPath = getRelativePath(pair.agentsPath, baseDir);
120→					const claudeRelPath = getRelativePath(pair.claudePath, baseDir);
121→
122→					const diff = createTwoFilesPatch(
123→						agentsRelPath,
124→						claudeRelPath,
125→						agentsNormalized,
126→						claudeNormalized,
127→						"AGENTS.md",
128→						"CLAUDE.md",
129→						{ context: 1 },
130→					);
131→
132→					// Count lines for location data
133→					const agentsLines = agentsContent.split("\n").length;
134→					const claudeLines = claudeContent.split("\n").length;
135→
136→					const locations: Location[] = [
137→						{
138→							file: agentsRelPath,
139→							start: 1,
140→							end: agentsLines,
141→						},
142→						{
143→							file: claudeRelPath,
144→							start: 1,
145→							end: claudeLines,
146→						},
147→					];
148→
149→					const issue: Issue = {
150→						category: "File Consistency",
151→						severity: 9,
152→						problem: "AGENTS.md and CLAUDE.md coexist with different content",
153→						description: `Found colocated AGENTS.md and CLAUDE.md files with different content in ${getRelativePath(pair.directory, baseDir)}. AI agents may receive inconsistent instructions.`,
154→						title: "Conflicting AGENTS.md and CLAUDE.md files",
155→						location: locations,
156→						affectedFiles: [agentsRelPath, claudeRelPath],
157→						isMultiFile: true,
158→						impact:
159→							"AI agents may receive inconsistent instructions depending on which file they reference, leading to unpredictable behavior.",
160→						fix: "Choose one naming standard (AGENTS.md or CLAUDE.md). Merge any unique content before renaming or deleting the duplicate.",
161→						context: `Unified Diff:\n\n${diff}`,
162→						issueType: "error",
163→						evaluatorName: "file-consistency",
164→					};
165→
166→					issues.push(issue);
167→
168→					if (verbose) {
169→						console.log(
170→							`[FileConsistencyValidator] Conflict found: ${agentsRelPath} vs ${claudeRelPath}`,
171→						);
172→					}
173→				} else {
174→					if (verbose) {
175→						const agentsRelPath = getRelativePath(pair.agentsPath, baseDir);
176→						console.log(
177→							`[FileConsistencyValidator] Files identical (no conflict): ${agentsRelPath}`,
178→						);
179→					}
180→				}
181→			} catch (error) {
182→				if (verbose) {
183→					console.error(
184→						`[FileConsistencyValidator] Error reading files in ${pair.directory}:`,
185→						error,
186→					);
187→				}
188→				// Continue with next pair even if one fails
189→			}
190→		}
191→
192→		return {
193→			issues,
194→			pairsChecked: pairs.length,
195→			conflictsFound,
196→		};
197→	} catch (error) {
198→		if (verbose) {
199→			console.error(
200→				"[FileConsistencyValidator] Error during validation:",
201→				error,
202→			);
203→		}
204→		// Return empty result on error
205→		return {
206→			issues: [],
207→			pairsChecked: 0,
208→			conflictsFound: 0,
209→		};
210→	}
211→}
