  9→import type { Issue, Location } from "@shared/types/evaluation";
 10→import { createTwoFilesPatch } from "diff";
 11→import { readFile } from "fs/promises";
 12→
 13→/**
 14→ * Strip Packmind standards section from content
 15→ * Removes content between <!-- start: Packmind standards --> and <!-- end: Packmind standards --> tags
 16→ * including the tags themselves
 17→ */
 18→function stripPackmindStandards(content: string): string {
 19→	const startTag = "<!-- start: Packmind standards -->";
 20→	const endTag = "<!-- end: Packmind standards -->";
 21→
 22→	const startIndex = content.indexOf(startTag);
 23→	if (startIndex === -1) {
 24→		return content;
 25→	}
 26→
 27→	const endIndex = content.indexOf(endTag, startIndex);
 28→	if (endIndex === -1) {
 29→		return content; // No closing tag found, return original
 30→	}
 31→
 32→	// Remove the section including tags
 33→	const before = content.slice(0, startIndex);
 34→	const after = content.slice(endIndex + endTag.length);
 35→
 36→	return before + after;
 37→}
 38→
 39→/**
 40→ * Normalize trailing newlines in content.
 41→ * Ensures consistent trailing newline behavior to prevent false positives
 42→ * when files differ only in trailing whitespace at EOF.
 43→ *
 44→ * Behavior:
 45→ * - Multiple trailing newlines -> single newline ("content\n\n\n" -> "content\n")
 46→ * - Single trailing newline -> preserved ("content\n" -> "content\n")
 47→ * - No trailing newline -> adds one ("content" -> "content\n")
 48→ */
 49→function normalizeTrailingNewlines(content: string): string {
 50→	return content.replace(/\n*$/, "\n");
 51→}
 52→
 53→/**
 54→ * Options for file consistency validation
 55→ */
 56→export interface ConsistencyValidationOptions {
 57→	verbose?: boolean;
 58→	agentsFiles?: string[]; // Optional: pre-discovered paths (not directly used but for consistency)
 59→}
 60→
 61→/**
 62→ * Result of consistency validation
 63→ */
 64→export interface ConsistencyValidationResult {
 65→	issues: Issue[];
 66→	pairsChecked: number;
 67→	conflictsFound: number;
 68→}
