172→								message: `Step completed: ${event.data?.step}`,
173→							},
174→						],
175→					}));
176→					break;
177→
178→				case "remediation.completed": {
179→					const remResult = event.data?.result as RemediationResult | undefined;
180→					setProgressState((prev) => ({
181→						...prev,
182→						status: "completed",
183→						result: remResult,
184→						logs: [
