187→						],
188→					}));
189→					if (remResult) {
190→						setResult(remResult);
191→					}
192→					setPhase("results");
193→					setSseUrl(null);
194→					break;
195→				}
196→
197→				case "remediation.failed":
198→					setProgressState((prev) => ({
199→						...prev,
200→						status: "failed",
201→						error: event.data?.error,
202→						logs: [
203→							...prev.logs,
204→							{
205→								timestamp,
206→								message: `Failed: ${event.data?.error?.message || "Unknown error"}`,
207→							},
208→						],
209→					}));
210→					setExecuteError(event.data?.error?.message || "Remediation failed");
211→					setPhase("config");
212→					setSseUrl(null);
213→					break;
214→			}
215→		},
216→		[],
217→	);
