  1→/**
  2→ * Remediation prompt generator.
  3→ *
  4→ * Generates copy-paste-ready AI agent prompts from evaluation results:
  5→ * - Error fix prompt: instructs an agent to fix documentation issues
  6→ * - Suggestion enrich prompt: instructs an agent to add missing documentation
  7→ */
  8→
  9→export interface RemediationIssue {
 10→	evaluatorName: string;
 11→	category: string;
 12→	title?: string;
 13→	problem?: string;
 14→	description?: string;
 15→	severity?: number;
 16→	impactLevel?: string;
 17→	location: { file?: string; start: number; end: number };
 18→	snippet?: string;
 19→	fix?: string;
 20→	recommendation?: string;
 21→}
 22→
 23→export interface RemediationInput {
 24→	targetFileType: "AGENTS.md" | "CLAUDE.md";
 25→	contextFilePaths: string[];
 26→	errors: RemediationIssue[];
 27→	suggestions: RemediationIssue[];
 28→	technicalInventorySection: string;
 29→	projectSummary: {
 30→		languages?: string;
 31→		frameworks?: string;
 32→		architecture?: string;
 33→	};
 34→}
 35→
 36→export interface RemediationPrompts {
 37→	errorFixPrompt: string;
 38→	suggestionEnrichPrompt: string;
 39→	errorCount: number;
 40→	suggestionCount: number;
 41→}
 42→
 43→function formatIssueDescription(issue: RemediationIssue): string {
 44→	return issue.problem || issue.description || issue.title || "No description";
 45→}
 46→
 47→function formatIssueFix(issue: RemediationIssue): string {
 48→	return issue.fix || issue.recommendation || "Review and fix this issue";
 49→}
 50→
 51→function formatProjectLine(
 52→	summary: RemediationInput["projectSummary"],
 53→): string {
 54→	const parts: string[] = [];
 55→	if (summary.languages) parts.push(`Languages: ${summary.languages}`);
 56→	if (summary.frameworks) parts.push(`Frameworks: ${summary.frameworks}`);
 57→	if (summary.architecture) parts.push(`Architecture: ${summary.architecture}`);
 58→	return parts.length > 0 ? parts.join(" | ") : "Not identified";
 59→}
 60→
 61→function formatErrorIssueBlock(issue: RemediationIssue, index: number): string {
 62→	const lines: string[] = [];
 63→	lines.push(`### ${index + 1}. ${issue.evaluatorName}: ${issue.category}`);
 64→	lines.push(`**Severity**: ${issue.severity ?? "N/A"}/10`);
 65→
 66→	if (issue.location.file) {
 67→		lines.push(
 68→			`**File**: ${issue.location.file}, lines ${issue.location.start}-${issue.location.end}`,
 69→		);
 70→	}
 71→
 72→	lines.push(`**Problem**: ${formatIssueDescription(issue)}`);
 73→
 74→	if (issue.snippet) {
 75→		lines.push("**Current content**:");
 76→		lines.push(`> ${issue.snippet.split("\n").join("\n> ")}`);
 77→	}
 78→
 79→	lines.push(`**Fix**: ${formatIssueFix(issue)}`);
 80→
 81→	return lines.join("\n");
 82→}
 83→
 84→function formatSuggestionIssueBlock(
 85→	issue: RemediationIssue,
 86→	index: number,
 87→): string {
 88→	const lines: string[] = [];
 89→	lines.push(`### ${index + 1}. ${issue.evaluatorName}: ${issue.category}`);
 90→	lines.push(`**Impact**: ${issue.impactLevel ?? "N/A"}`);
 91→
 92→	if (issue.location.file) {
 93→		lines.push(
 94→			`**File**: ${issue.location.file}, lines ${issue.location.start}-${issue.location.end}`,
 95→		);
 96→	}
 97→
 98→	lines.push(`**Gap**: ${formatIssueDescription(issue)}`);
 99→
100→	if (issue.snippet) {
101→		lines.push("**Current content**:");
102→		lines.push(`> ${issue.snippet.split("\n").join("\n> ")}`);
103→	}
104→
105→	lines.push(`**Recommendation**: ${formatIssueFix(issue)}`);
106→
107→	return lines.join("\n");
108→}
109→
110→function buildErrorFixPrompt(input: RemediationInput): string {
111→	if (input.errors.length === 0) {
112→		return "";
113→	}
114→
115→	// Sort by severity descending
116→	const sorted = [...input.errors].sort(
117→		(a, b) => (b.severity ?? 0) - (a.severity ?? 0),
118→	);
119→
120→	const contextFilesList = input.contextFilePaths
121→		.map((p) => `- ${p}`)
122→		.join("\n");
123→	const issueBlocks = sorted
124→		.map((issue, i) => formatErrorIssueBlock(issue, i))
125→		.join("\n\n");
126→
127→	return `# Fix Documentation Issues
128→
129→## Role
130→You are fixing documentation quality issues in ${input.targetFileType} files.
131→These files guide AI coding agents. Fixes must be precise and concise.
132→
133→## Context Files
134→${contextFilesList}
135→
136→${input.technicalInventorySection ? `## Technical Context\n${input.technicalInventorySection}\n` : ""}## Project
137→${formatProjectLine(input.projectSummary)}
138→
139→## Issues to Fix (${input.errors.length})
140→
141→${issueBlocks}
142→
143→## Instructions
144→1. Read the target files from disk before making changes
145→2. Use your own judgment to assess each issue: these were produced by an automated evaluator and some may be false positives or irrelevant given the actual file content. Skip any issue that is not a real problem after reading the file
146→3. Fix each remaining issue, highest severity first
147→4. Preserve all correct existing content
148→5. Keep changes minimal — only fix what's genuinely flagged
149→6. Do not add commentary, headers, or sections beyond what's needed
150→7. After making all changes, output a JSON summary:
151→\`\`\`json
152→{
153→  "actions": [
154→    { "issueIndex": 1, "status": "fixed", "file": "AGENTS.md", "summary": "Replaced vague setup instructions with exact commands" },
155→    { "issueIndex": 2, "status": "skipped", "summary": "Not a real issue after reading the file" }
156→  ]
157→}
158→\`\`\`
159→Use issue numbers from above. Status: "fixed" or "skipped". Keep summaries under 15 words.`;
160→}
161→
162→function buildSuggestionEnrichPrompt(input: RemediationInput): string {
163→	if (input.suggestions.length === 0) {
164→		return "";
165→	}
166→
167→	// Sort by impact level: High > Medium > Low
168→	const impactOrder: Record<string, number> = { High: 0, Medium: 1, Low: 2 };
169→	const sorted = [...input.suggestions].sort(
170→		(a, b) =>
171→			(impactOrder[a.impactLevel ?? "Low"] ?? 2) -
172→			(impactOrder[b.impactLevel ?? "Low"] ?? 2),
173→	);
174→
175→	const contextFilesList = input.contextFilePaths
176→		.map((p) => `- ${p}`)
177→		.join("\n");
178→	const issueBlocks = sorted
179→		.map((issue, i) => formatSuggestionIssueBlock(issue, i))
180→		.join("\n\n");
181→
182→	return `# Enrich Documentation
183→
184→## Role
185→You are enriching AI agent documentation in ${input.targetFileType} files.
186→These files guide AI coding agents. Additions must be accurate and concise.
187→
188→## Context Files
189→${contextFilesList}
190→
191→${input.technicalInventorySection ? `## Technical Context\n${input.technicalInventorySection}\n` : ""}## Project
192→${formatProjectLine(input.projectSummary)}
193→
194→## Documentation Gaps (${input.suggestions.length})
195→
196→${issueBlocks}
197→
198→## Instructions
199→1. Read the target files and scan the codebase before making changes
200→2. Use your own judgment to assess each gap: these were produced by an automated evaluator and some may be false positives or irrelevant given the actual codebase. Skip any suggestion that is not genuinely useful after reviewing the code
201→3. Address each remaining gap, highest impact first
202→4. Add concise, accurate documentation based on actual codebase analysis
203→5. Create new ${input.targetFileType} files in subdirectories if recommended
204→6. Preserve all correct existing content
205→7. Keep additions minimal — only add what's needed to close the gap
206→8. After making all changes, output a JSON summary:
207→\`\`\`json
208→{
209→  "actions": [
210→    { "issueIndex": 1, "status": "added", "file": "AGENTS.md", "summary": "Added testing patterns section with Jest conventions" },
211→    { "issueIndex": 2, "status": "skipped", "summary": "Already documented in existing section" }
212→  ]
213→}
214→\`\`\`
215→Use gap numbers from above. Status: "added" or "skipped". Keep summaries under 15 words.`;
216→}
217→
218→export function generateRemediationPrompts(
219→	input: RemediationInput,
220→): RemediationPrompts {
221→	return {
222→		errorFixPrompt: buildErrorFixPrompt(input),
223→		suggestionEnrichPrompt: buildSuggestionEnrichPrompt(input),
224→		errorCount: input.errors.length,
225→		suggestionCount: input.suggestions.length,
226→	};
227→}
