101→	// Resolve selected issue keys to actual issues, split by type
102→	const { errorEntries, suggestionEntries } = useMemo(() => {
103→		const errors: { key: string; issue: Issue }[] = [];
104→		const suggestions: { key: string; issue: Issue }[] = [];
105→
106→		for (const key of selectedIssueKeys) {
107→			const issue = issueKeyMap.get(key);
