 41→}
 42→
 43→export function RemediateTab({
 44→	evaluationId,
 45→	evaluationData,
 46→	selectedIssueKeys,
 47→	issueKeyMap,
 48→	onRemoveIssue,
 49→	onClearAll,
 50→}: RemediateTabProps) {
 51→	const api = useEvaluationApi();
 52→	const providerDetection = useProviderDetection();
 53→
 54→	const [phase, setPhase] = useState<Phase>("config");
 55→	const [targetFileType, setTargetFileType] = useState<
 56→		"AGENTS.md" | "CLAUDE.md"
 57→	>("AGENTS.md");
 58→	const [selectedProvider, setSelectedProvider] =
 59→		useState<ProviderName>("claude");
 60→	const [isExecuting, setIsExecuting] = useState(false);
 61→	const [executeError, setExecuteError] = useState<string | null>(null);
 62→
 63→	// SSE state
 64→	const [sseUrl, setSseUrl] = useState<string | null>(null);
 65→	const [remediationId, setRemediationId] = useState<string | null>(null);
 66→	const [progressState, setProgressState] = useState<IRemediationProgressState>(
 67→		{
 68→			status: "queued",
 69→			logs: [],
 70→		},
 71→	);
 72→
 73→	// Results state
 74→	const [result, setResult] = useState<RemediationResult | null>(null);
 75→
 76→	// Legacy prompt generation state
 77→	const [isGenerating, setIsGenerating] = useState(false);
 78→	const [generateError, setGenerateError] = useState<string | null>(null);
 79→	const [prompts, setPrompts] = useState<RemediationPromptsResponse | null>(
 80→		null,
 81→	);
 82→
 83→	// Detect providers on mount
 84→	useEffect(() => {
 85→		if (providerDetection.status === "idle") {
 86→			providerDetection.detectProviders();
 87→		}
 88→	}, [providerDetection]);
 89→
 90→	// Available providers for the selector
 91→	const availableProviders = useMemo(() => {
 92→		const providers: ProviderStatus[] = [];
 93→		for (const p of providerDetection.providers.values()) {
 94→			if (p.available && p.name !== "random") {
 95→				providers.push(p);
 96→			}
 97→		}
 98→		return providers;
 99→	}, [providerDetection.providers]);
100→
101→	// Resolve selected issue keys to actual issues, split by type
102→	const { errorEntries, suggestionEntries } = useMemo(() => {
103→		const errors: { key: string; issue: Issue }[] = [];
104→		const suggestions: { key: string; issue: Issue }[] = [];
105→
106→		for (const key of selectedIssueKeys) {
107→			const issue = issueKeyMap.get(key);
108→			if (!issue) continue;
109→			const type = getIssueType(issue);
110→			if (type === "error") {
111→				errors.push({ key, issue });
112→			} else {
113→				suggestions.push({ key, issue });
114→			}
115→		}
116→
117→		errors.sort(
118→			(a, b) => getIssueSeverity(b.issue) - getIssueSeverity(a.issue),
119→		);
120→		const impactOrder: Record<string, number> = {
121→			High: 0,
122→			Medium: 1,
123→			Low: 2,
124→		};
125→		suggestions.sort(
126→			(a, b) =>
127→				(impactOrder[a.issue.impactLevel ?? "Low"] ?? 2) -
128→				(impactOrder[b.issue.impactLevel ?? "Low"] ?? 2),
129→		);
130→
131→		return { errorEntries: errors, suggestionEntries: suggestions };
132→	}, [selectedIssueKeys, issueKeyMap]);
133→
134→	const totalSelected = errorEntries.length + suggestionEntries.length;
135→
136→	// SSE message handler
137→	const handleSSEMessage = useCallback(
138→		// biome-ignore lint/suspicious/noExplicitAny: SSE event data varies by type
139→		(event: any) => {
140→			const timestamp = new Date().toISOString();
141→
142→			switch (event.type) {
143→				case "remediation.started":
144→					setProgressState((prev) => ({
145→						...prev,
146→						status: "running",
147→						logs: [...prev.logs, { timestamp, message: "Remediation started" }],
148→					}));
149→					break;
150→
151→				case "remediation.step.started": {
152→					const bi = event.data?.batchInfo as
153→						| { batchNumber: number; totalBatches: number }
154→						| undefined;
155→					const batchLabel = bi
156→						? ` (batch ${bi.batchNumber}/${bi.totalBatches})`
157→						: "";
158→					setProgressState((prev) => ({
159→						...prev,
160→						currentStep: event.data?.step,
161→						batchInfo: bi,
162→						logs: [
163→							...prev.logs,
164→							{
165→								timestamp,
166→								message: `Step started: ${event.data?.step}${batchLabel}`,
167→							},
168→						],
169→					}));
170→					break;
171→				}
172→
173→				case "remediation.step.completed": {
174→					const bi2 = event.data?.batchInfo as
175→						| { batchNumber: number; totalBatches: number }
176→						| undefined;
177→					const batchLabel2 = bi2
178→						? ` (batch ${bi2.batchNumber}/${bi2.totalBatches})`
179→						: "";
180→					setProgressState((prev) => ({
181→						...prev,
182→						batchInfo: undefined,
183→						logs: [
184→							...prev.logs,
185→							{
186→								timestamp,
187→								message: `Step completed: ${event.data?.step}${batchLabel2}`,
188→							},
189→						],
190→					}));
191→					break;
192→				}
193→
194→				case "remediation.completed": {
195→					const remResult = event.data?.result as RemediationResult | undefined;
196→					setProgressState((prev) => ({
197→						...prev,
198→						status: "completed",
199→						result: remResult,
200→						logs: [
201→							...prev.logs,
202→							{ timestamp, message: "Remediation completed" },
203→						],
204→					}));
205→					if (remResult) {
206→						setResult(remResult);
207→					}
208→					setPhase("results");
209→					setSseUrl(null);
210→					break;
211→				}
212→
213→				case "remediation.failed":
214→					setProgressState((prev) => ({
215→						...prev,
216→						status: "failed",
217→						error: event.data?.error,
218→						logs: [
219→							...prev.logs,
220→							{
221→								timestamp,
222→								message: `Failed: ${event.data?.error?.message || "Unknown error"}`,
223→							},
224→						],
225→					}));
226→					setExecuteError(event.data?.error?.message || "Remediation failed");
227→					setPhase("config");
228→					setSseUrl(null);
229→					break;
230→			}
231→		},
232→		[],
233→	);
234→
235→	useSSE({
236→		url: sseUrl,
237→		onMessage: handleSSEMessage,
238→	});
239→
240→	// Execute remediation
241→	const handleExecute = useCallback(async () => {
242→		if (!evaluationId || totalSelected === 0) return;
243→
244→		setIsExecuting(true);
245→		setExecuteError(null);
246→		setPrompts(null);
247→
248→		try {
249→			const issues = [
250→				...errorEntries.map((e) => e.issue),
251→				...suggestionEntries.map((e) => e.issue),
252→			];
253→
254→			const response = await api.executeRemediation(
255→				evaluationId,
256→				issues,
257→				targetFileType,
258→				selectedProvider,
259→			);
260→
261→			setRemediationId(response.remediationId);
262→			setSseUrl(response.sseUrl);
263→			setProgressState({ status: "queued", logs: [] });
264→			setPhase("progress");
265→		} catch (err) {
266→			setExecuteError(
267→				err instanceof Error ? err.message : "Failed to start remediation",
268→			);
269→		} finally {
270→			setIsExecuting(false);
271→		}
272→	}, [
273→		evaluationId,
274→		totalSelected,
275→		errorEntries,
276→		suggestionEntries,
277→		targetFileType,
278→		selectedProvider,
279→		api,
280→	]);
281→
282→	// Generate prompts (legacy copy-paste mode)
283→	const handleGeneratePrompts = useCallback(async () => {
284→		if (!evaluationId || totalSelected === 0) return;
285→
286→		setIsGenerating(true);
287→		setGenerateError(null);
288→
289→		try {
290→			const issues = [
291→				...errorEntries.map((e) => e.issue),
292→				...suggestionEntries.map((e) => e.issue),
293→			];
294→			const result = await api.generateRemediationPrompts(
295→				evaluationId,
296→				issues,
297→				targetFileType,
298→			);
299→			setPrompts(result);
300→		} catch (err) {
301→			setGenerateError(
302→				err instanceof Error ? err.message : "Failed to generate prompts",
303→			);
304→		} finally {
305→			setIsGenerating(false);
306→		}
307→	}, [
308→		evaluationId,
309→		totalSelected,
310→		errorEntries,
311→		suggestionEntries,
312→		targetFileType,
313→		api,
314→	]);
315→
316→	const handleBackToConfig = useCallback(() => {
