846→ */
847→function getFileSummaries(
848→	filePath: string,
849→	result: RemediationResult,
850→): RemediationAction[] {
851→	if (!result.summary?.parsed) return [];
852→
853→	const allActions = [
854→		...result.summary.errorFixActions,
855→		...result.summary.suggestionEnrichActions,
856→	];
857→
858→	return allActions.filter(
859→		(a) => a.file && a.status !== "skipped" && filePath.endsWith(a.file),
860→	);
861→}
