   276→						setResult(remResult);
   277→					}
   278→					setPhase("results");
   279→					setSseUrl(null);
   280→					break;
   281→				}
   282→
   283→				case "remediation.failed":
   284→					setProgressState((prev) => ({
   285→						...prev,
   286→						status: "failed",
   287→						error: event.data?.error,
   288→						logs: [
   289→							...prev.logs,
   290→							{
   291→								timestamp,
   292→								message: `Failed: ${event.data?.error?.message || "Unknown error"}`,
   293→							},
   294→						],
   295→					}));
   296→					setExecuteError(event.data?.error?.message || "Remediation failed");
   297→					setPhase("config");
   298→					setSseUrl(null);
   299→					break;
   300→			}
   301→		},
   302→		[],
   303→	);
