   888→									viewBox="0 0 24 24"
   889→									stroke="currentColor"
   890→								>
   891→									<path
   892→										strokeLinecap="round"
   893→										strokeLinejoin="round"
   894→										strokeWidth={2}
   895→										d="M5 13l4 4L19 7"
   896→									/>
   897→								</svg>
   898→							</span>
   899→						)}
   900→						<span className="text-sm text-slate-300 flex-1">
   901→							{action.issueTitle ? (
   902→								<span className="text-slate-400 text-xs mr-1.5">
   903→									{action.issueTitle}
   904→								</span>
   905→							) : (
   906→								<span className="text-slate-400 font-mono text-xs mr-1.5">
   907→									#{action.issueIndex}
   908→								</span>
   909→							)}
   910→							{action.summary}
   911→						</span>
   912→						{action.file && (
   913→							<span className="text-xs text-slate-500 font-mono flex-shrink-0">
   914→								{action.file}
   915→							</span>
   916→						)}
   917→					</div>
   918→				))}
   919→			</div>
