   921→	);
   922→}
   923→
   924→/**
   925→ * Get action summaries relevant to a specific file path.
   926→ */
   927→function getFileSummaries(
   928→	filePath: string,
   929→	result: RemediationResult,
   930→): RemediationAction[] {
   931→	if (!result.summary?.parsed) return [];
   932→
   933→	const allActions = [
   934→		...result.summary.errorFixActions,
   935→		...result.summary.suggestionEnrichActions,
   936→	];
   937→
   938→	return allActions.filter(
   939→		(a) => a.file && a.status !== "skipped" && filePath.endsWith(a.file),
   940→	);
   941→}
