 60→	const [isExecuting, setIsExecuting] = useState(false);
 61→	const [executeError, setExecuteError] = useState<string | null>(null);
 62→
 63→	// SSE state
 64→	const [sseUrl, setSseUrl] = useState<string | null>(null);
 65→	const [remediationId, setRemediationId] = useState<string | null>(null);
 66→	const [progressState, setProgressState] = useState<IRemediationProgressState>(
 67→		{
 68→			status: "queued",
 69→			logs: [],
 70→		},
 71→	);
 72→
 73→	// Results state
 74→	const [result, setResult] = useState<RemediationResult | null>(null);
 75→
 76→	// Legacy prompt generation state
 77→	const [isGenerating, setIsGenerating] = useState(false);
 78→	const [generateError, setGenerateError] = useState<string | null>(null);
 79→	const [prompts, setPrompts] = useState<RemediationPromptsResponse | null>(
 80→		null,
 81→	);
 82→
 83→	// Detect providers on mount
 84→	useEffect(() => {
 85→		if (providerDetection.status === "idle") {
 86→			providerDetection.detectProviders();
 87→		}
 88→	}, [providerDetection]);
 89→
 90→	// Available providers for the selector
 91→	const availableProviders = useMemo(() => {
 92→		const providers: ProviderStatus[] = [];
 93→		for (const p of providerDetection.providers.values()) {
 94→			if (p.available && p.name !== "random") {
 95→				providers.push(p);
 96→			}
 97→		}
 98→		return providers;
 99→	}, [providerDetection.providers]);
100→
101→	// Resolve selected issue keys to actual issues, split by type
102→	const { errorEntries, suggestionEntries } = useMemo(() => {
103→		const errors: { key: string; issue: Issue }[] = [];
104→		const suggestions: { key: string; issue: Issue }[] = [];
105→
106→		for (const key of selectedIssueKeys) {
107→			const issue = issueKeyMap.get(key);
108→			if (!issue) continue;
109→			const type = getIssueType(issue);
110→			if (type === "error") {
111→				errors.push({ key, issue });
112→			} else {
113→				suggestions.push({ key, issue });
114→			}
115→		}
116→
117→		errors.sort(
118→			(a, b) => getIssueSeverity(b.issue) - getIssueSeverity(a.issue),
119→		);
120→		const impactOrder: Record<string, number> = {
121→			High: 0,
122→			Medium: 1,
123→			Low: 2,
124→		};
125→		suggestions.sort(
126→			(a, b) =>
127→				(impactOrder[a.issue.impactLevel ?? "Low"] ?? 2) -
128→				(impactOrder[b.issue.impactLevel ?? "Low"] ?? 2),
129→		);
130→
131→		return { errorEntries: errors, suggestionEntries: suggestions };
132→	}, [selectedIssueKeys, issueKeyMap]);
133→
134→	const totalSelected = errorEntries.length + suggestionEntries.length;
135→
136→	// SSE message handler
137→	const handleSSEMessage = useCallback(
138→		// biome-ignore lint/suspicious/noExplicitAny: SSE event data varies by type
139→		(event: any) => {
140→			const timestamp = new Date().toISOString();
141→
142→			switch (event.type) {
143→				case "remediation.started":
144→					setProgressState((prev) => ({
145→						...prev,
146→						status: "running",
147→						logs: [...prev.logs, { timestamp, message: "Remediation started" }],
148→					}));
149→					break;
150→
151→				case "remediation.progress": {
152→					const d = event.data ?? {};
153→					setProgressState((prev) => ({
154→						...prev,
155→						...(d.errorCount !== undefined && {
156→							errorCount: d.errorCount as number,
157→						}),
158→						...(d.suggestionCount !== undefined && {
159→							suggestionCount: d.suggestionCount as number,
160→						}),
161→						...(d.totalBatches !== undefined && {
162→							totalBatches: d.totalBatches as number,
163→						}),
164→						...(d.completedBatches !== undefined && {
165→							completedBatches: d.completedBatches as number,
166→						}),
167→						...(d.phase !== undefined && {
168→							currentPhase: d.phase as "errors" | "suggestions",
169→						}),
170→						...(d.runningTotalCostUsd !== undefined && {
171→							runningTotalCostUsd: d.runningTotalCostUsd as number,
172→						}),
173→						...(d.runningTotalDurationMs !== undefined && {
174→							runningTotalDurationMs: d.runningTotalDurationMs as number,
175→						}),
176→						...(d.runningTotalInputTokens !== undefined && {
177→							runningTotalInputTokens: d.runningTotalInputTokens as number,
178→						}),
179→						...(d.runningTotalOutputTokens !== undefined && {
180→							runningTotalOutputTokens: d.runningTotalOutputTokens as number,
181→						}),
182→					}));
183→					break;
184→				}
185→
186→				case "remediation.step.started": {
187→					const bi = event.data?.batchInfo as
188→						| { batchNumber: number; totalBatches: number }
189→						| undefined;
190→					const batchLabel = bi
191→						? ` (batch ${bi.batchNumber}/${bi.totalBatches})`
192→						: "";
193→					const issueSummaries = event.data?.issuesSummary as
194→						| string[]
195→						| undefined;
196→					setProgressState((prev) => ({
197→						...prev,
198→						currentStep: event.data?.step,
199→						batchInfo: bi,
200→						...(issueSummaries && { currentBatchIssues: issueSummaries }),
201→						logs: [
202→							...prev.logs,
203→							{
204→								timestamp,
205→								message: `Step started: ${event.data?.step}${batchLabel}`,
206→							},
207→						],
208→					}));
209→					break;
210→				}
211→
212→				case "remediation.step.completed": {
213→					const bi2 = event.data?.batchInfo as
214→						| { batchNumber: number; totalBatches: number }
215→						| undefined;
216→					const batchLabel2 = bi2
217→						? ` (batch ${bi2.batchNumber}/${bi2.totalBatches})`
218→						: "";
219→					const step = event.data?.step as string | undefined;
220→					const batchDurationMs = event.data?.batchDurationMs as
221→						| number
222→						| undefined;
223→					const batchCostUsd = event.data?.batchCostUsd as number | undefined;
224→					const batchInputTokens = event.data?.batchInputTokens as
225→						| number
226→						| undefined;
227→					const batchOutputTokens = event.data?.batchOutputTokens as
228→						| number
229→						| undefined;
230→
231→					const hasBatchStats =
232→						batchDurationMs !== undefined && batchCostUsd !== undefined;
233→					let logMessage = `Step completed: ${step}${batchLabel2}`;
234→					if (hasBatchStats) {
235→						const phaseName =
236→							step === "executing_error_fix"
237→								? "Error fix"
238→								: "Suggestion enrich";
239→						const label = bi2
240→							? `${phaseName} batch ${bi2.batchNumber}/${bi2.totalBatches}`
241→							: phaseName;
242→						logMessage = `${label} completed: ${Math.round(batchDurationMs / 1000)}s, $${batchCostUsd.toFixed(4)}`;
243→					}
244→
245→					setProgressState((prev) => ({
246→						...prev,
247→						batchInfo: undefined,
248→						currentBatchIssues: undefined,
249→						...(hasBatchStats && {
250→							lastBatchStats: {
251→								durationMs: batchDurationMs!,
252→								costUsd: batchCostUsd!,
253→								inputTokens: batchInputTokens ?? 0,
254→								outputTokens: batchOutputTokens ?? 0,
255→							},
256→						}),
257→						logs: [...prev.logs, { timestamp, message: logMessage }],
258→					}));
259→					break;
260→				}
261→
262→				case "remediation.completed": {
263→					const remResult = event.data?.result as RemediationResult | undefined;
264→					setProgressState((prev) => ({
265→						...prev,
266→						status: "completed",
267→						result: remResult,
268→						logs: [
269→							...prev.logs,
270→							{ timestamp, message: "Remediation completed" },
271→						],
272→					}));
273→					if (remResult) {
274→						setResult(remResult);
275→					}
276→					setPhase("results");
277→					setSseUrl(null);
278→					break;
279→				}
280→
281→				case "remediation.failed":
282→					setProgressState((prev) => ({
283→						...prev,
284→						status: "failed",
285→						error: event.data?.error,
286→						logs: [
287→							...prev.logs,
288→							{
289→								timestamp,
290→								message: `Failed: ${event.data?.error?.message || "Unknown error"}`,
291→							},
292→						],
293→					}));
294→					setExecuteError(event.data?.error?.message || "Remediation failed");
295→					setPhase("config");
296→					setSseUrl(null);
297→					break;
298→			}
299→		},
300→		[],
301→	);
302→
303→	useSSE({
304→		url: sseUrl,
305→		onMessage: handleSSEMessage,
306→	});
307→
