374→		}
375→	}, [
376→		evaluationId,
377→		totalSelected,
378→		errorEntries,
379→		suggestionEntries,
380→		targetFileType,
381→		api,
382→	]);
383→
384→	const handleBackToConfig = useCallback(() => {
385→		setPhase("config");
386→		setResult(null);
387→		setRemediationId(null);
388→		setSseUrl(null);
