492→										in {Math.round(result.totalDurationMs / 1000)}s
493→									</span>
494→								)}
495→								{result.totalCostUsd > 0 && (
496→									<span className="text-slate-500 ml-2">
497→										(${result.totalCostUsd.toFixed(4)})
498→									</span>
499→								)}
500→							</p>
501→							{(result.totalInputTokens > 0 ||
502→								result.totalOutputTokens > 0) && (
503→								<p className="text-caption mt-1">
504→									{result.totalInputTokens.toLocaleString()} input /{" "}
505→									{result.totalOutputTokens.toLocaleString()} output tokens
506→									{hasPerPromptStats && (
507→										<span className="text-slate-500">
508→											{" "}
509→											&mdash;{" "}
510→											{result.errorFixStats && (
511→												<span>
512→													Error fix: $
