514→													{result.suggestionEnrichStats && " | "}
515→												</span>
516→											)}
517→											{result.suggestionEnrichStats && (
518→												<span>
519→													Enrich: $
520→													{(result.suggestionEnrichStats.costUsd ?? 0).toFixed(
521→														4,
522→													)}
523→												</span>
524→											)}
525→										</span>
526→									)}
527→								</p>
528→							)}
529→						</div>
530→						<div className="flex items-center gap-2">
531→							{remediationId && <PatchDownload remediationId={remediationId} />}
532→							<button onClick={handleBackToConfig} className="btn-secondary">
