922→/**
923→ * Get action summaries relevant to a specific file path.
924→ */
925→function getFileSummaries(
926→	filePath: string,
927→	result: RemediationResult,
928→): RemediationAction[] {
929→	if (!result.summary?.parsed) return [];
930→
931→	const allActions = [
932→		...result.summary.errorFixActions,
933→		...result.summary.suggestionEnrichActions,
934→	];
935→
936→	return allActions.filter(
937→		(a) => a.file && a.status !== "skipped" && filePath.endsWith(a.file),
938→	);
939→}
