116→export function useEvaluationApi(): IUseEvaluationApiReturn {
117→	const [isLoading, setIsLoading] = useState(false);
118→	const [error, setError] = useState<string | null>(null);
119→
120→	const submitJob = useCallback(
121→		async (
122→			repositoryUrl: string,
123→			evaluators?: number,
124→			provider?: ProviderName,
125→			evaluatorFilter?: EvaluatorFilter,
126→			timeout?: number,
127→			concurrency?: number,
128→			selectedEvaluators?: string[],
129→		): Promise<IEvaluateResponse> => {
130→			setIsLoading(true);
131→			setError(null);
132→
133→			try {
134→				const response = await fetch("/api/evaluate", {
135→					method: "POST",
136→					headers: { "Content-Type": "application/json" },
137→					body: JSON.stringify({
138→						repositoryUrl,
139→						options: {
140→							...(evaluators ? { evaluators } : {}),
141→							...(provider ? { provider } : {}),
142→							...(evaluatorFilter ? { evaluatorFilter } : {}),
143→							...(timeout ? { timeout } : {}),
144→							...(concurrency ? { concurrency } : {}),
145→							...(selectedEvaluators ? { selectedEvaluators } : {}),
146→						},
147→					}),
148→				});
149→
150→				if (!response.ok) {
151→					const errorData = await response.json().catch(() => ({}));
152→
153→					// Handle queue full error (429) with user-friendly message
154→					if (response.status === 429 || errorData.code === "QUEUE_FULL") {
155→						throw new Error(
156→							"The evaluation queue is currently at capacity. Please wait a few moments for running evaluations to complete, then try again.",
157→						);
158→					}
159→
160→					throw new Error(errorData.error || `HTTP error ${response.status}`);
161→				}
162→
163→				const data = await response.json();
164→
165→				// Ensure sseUrl is an absolute URL
166→				if (data.sseUrl && data.sseUrl.startsWith("/")) {
167→					data.sseUrl = `${window.location.origin}${data.sseUrl}`;
168→				}
169→
170→				return data as IEvaluateResponse;
171→			} catch (err) {
172→				const message =
173→					err instanceof Error
174→						? err.message
175→						: "Failed to submit evaluation job";
176→				setError(message);
177→				throw err;
178→			} finally {
179→				setIsLoading(false);
180→			}
181→		},
182→		[],
183→	);
184→
185→	const getJobStatus = useCallback(
186→		async (jobId: string): Promise<IJobStatusResponse> => {
187→			try {
188→				const response = await fetch(`/api/evaluate/${jobId}`, {
189→					method: "GET",
190→					headers: { "Content-Type": "application/json" },
191→				});
192→
193→				if (!response.ok) {
194→					const errorData = await response.json().catch(() => ({}));
195→					throw new Error(errorData.error || `HTTP error ${response.status}`);
196→				}
197→
198→				return (await response.json()) as IJobStatusResponse;
199→			} catch (err) {
200→				const message =
201→					err instanceof Error ? err.message : "Failed to get job status";
202→				setError(message);
203→				throw err;
204→			}
205→		},
206→		[],
207→	);
208→
209→	const cancelJob = useCallback(async (jobId: string): Promise<void> => {
210→		try {
211→			const response = await fetch(`/api/evaluate/${jobId}`, {
212→				method: "DELETE",
213→				headers: { "Content-Type": "application/json" },
214→			});
215→
216→			if (!response.ok && response.status !== 404) {
217→				const errorData = await response.json().catch(() => ({}));
218→				throw new Error(errorData.error || `HTTP error ${response.status}`);
219→			}
220→		} catch (err) {
221→			// Silently handle cancel errors - job might already be completed
222→			console.warn("[API] Cancel job error:", err);
223→		}
224→	}, []);
225→
226→	const submitBatch = useCallback(
227→		async (
228→			urls: string[],
229→			evaluators?: number,
230→			provider?: ProviderName,
231→			evaluatorFilter?: EvaluatorFilter,
232→			timeout?: number,
233→			concurrency?: number,
234→			selectedEvaluators?: string[],
235→		): Promise<IBatchEvaluateResponse> => {
236→			setIsLoading(true);
237→			setError(null);
238→
239→			try {
240→				const response = await fetch("/api/evaluate/batch", {
241→					method: "POST",
242→					headers: { "Content-Type": "application/json" },
243→					body: JSON.stringify({
244→						urls,
245→						options: {
246→							...(evaluators ? { evaluators } : {}),
247→							...(provider ? { provider } : {}),
248→							...(evaluatorFilter ? { evaluatorFilter } : {}),
249→							...(timeout ? { timeout } : {}),
250→							...(concurrency ? { concurrency } : {}),
251→							...(selectedEvaluators ? { selectedEvaluators } : {}),
252→						},
253→					}),
254→				});
255→
256→				if (!response.ok) {
257→					const errorData = await response.json().catch(() => ({}));
258→					throw new Error(errorData.error || `HTTP error ${response.status}`);
259→				}
