 31→function issueToRemediationIssue(
 32→	issue: Issue & { evaluatorName?: string },
 33→): RemediationIssue {
 34→	const loc = Array.isArray(issue.location)
 35→		? issue.location[0]
 36→		: issue.location;
 37→	return {
 38→		evaluatorName: issue.evaluatorName || "unknown",
 39→		category: issue.category,
 40→		title: issue.title,
 41→		problem: issue.problem,
 42→		description: issue.description,
 43→		severity: issue.issueType === "error" ? issue.severity : undefined,
 44→		impactLevel:
 45→			issue.issueType === "suggestion" ? issue.impactLevel : undefined,
 46→		location: {
 47→			file: loc?.file,
 48→			start: loc?.start ?? 0,
 49→			end: loc?.end ?? 0,
 50→		},
 51→		snippet: issue.snippet,
 52→		fix: issue.fix,
 53→		recommendation: issue.recommendation,
 54→	};
 55→}
