 64→	async generatePrompts(req: Request): Promise<Response> {
 65→		try {
 66→			const body = (await req.json()) as GeneratePromptsRequest;
 67→
 68→			if (!body.evaluationId) {
 69→				return errorResponse(
 70→					"evaluationId is required",
 71→					"INVALID_REQUEST",
 72→					400,
 73→				);
 74→			}
 75→			if (!body.issues || body.issues.length === 0) {
 76→				return errorResponse(
 77→					"issues must be a non-empty array",
 78→					"INVALID_REQUEST",
 79→					400,
 80→				);
 81→			}
 82→			if (!body.targetFileType) {
 83→				return errorResponse(
 84→					"targetFileType is required",
 85→					"INVALID_REQUEST",
 86→					400,
 87→				);
 88→			}
 89→
 90→			// Step 1: Look up evaluation for context data (job store first, then database)
 91→			let evaluationData = null;
 92→
 93→			const job = this.jobManager.getJob(body.evaluationId);
 94→			if (job?.result) {
 95→				evaluationData = job.result;
 96→			} else {
 97→				const record = evaluationRepository.getEvaluationById(
 98→					body.evaluationId,
 99→				);
100→				if (record?.result) {
101→					evaluationData = record.result;
102→				}
103→			}
104→
105→			if (!evaluationData) {
106→				return notFoundResponse("Evaluation not found or has no results");
107→			}
108→
109→			// Step 2: Map provided issues directly to remediation format
110→			const errors: RemediationIssue[] = [];
111→			const suggestions: RemediationIssue[] = [];
112→
113→			for (const issue of body.issues) {
114→				const remIssue = issueToRemediationIssue(issue);
115→				if (issue.issueType === "suggestion") {
116→					suggestions.push(remIssue);
117→				} else {
118→					errors.push(remIssue);
119→				}
120→			}
121→
122→			// Step 3: Build technical inventory section
123→			const technicalInventorySection = buildTechnicalInventorySection(
124→				evaluationData.metadata?.projectContext?.technicalInventory,
125→			);
126→
127→			// Step 4: Build project summary
128→			const pc = evaluationData.metadata?.projectContext;
129→			const projectSummary = {
130→				languages: pc?.languages,
131→				frameworks: pc?.frameworks,
132→				architecture: pc?.architecture,
133→			};
134→
135→			// Step 5: Get context file paths
136→			const contextFilePaths = pc?.agentsFilePaths ?? [];
137→
138→			// Step 6: Generate prompts
139→			const input: RemediationInput = {
140→				targetFileType: body.targetFileType,
141→				contextFilePaths,
142→				errors,
143→				suggestions,
144→				technicalInventorySection,
145→				projectSummary,
146→			};
147→
148→			const result = generateRemediationPrompts(input);
149→
150→			return okResponse(result);
151→		} catch (err: unknown) {
152→			console.error("[RemediationRoutes] Error generating prompts:", err);
153→			return internalErrorResponse("Failed to generate remediation prompts");
154→		}
155→	}
156→
157→	/**
158→	 * POST /api/remediation/execute — Start a remediation execution job
159→	 */
160→	async execute(req: Request): Promise<Response> {
161→		try {
162→			if (!this.remediationJobManager) {
163→				return errorResponse(
164→					"Remediation execution is not available",
165→					"NOT_AVAILABLE",
166→					503,
167→				);
168→			}
169→
170→			const body = (await req.json()) as IRemediationRequest;
171→
172→			if (!body.evaluationId) {
173→				return errorResponse(
174→					"evaluationId is required",
175→					"INVALID_REQUEST",
176→					400,
177→				);
178→			}
179→			if (!body.issues || body.issues.length === 0) {
180→				return errorResponse(
181→					"issues must be a non-empty array",
182→					"INVALID_REQUEST",
183→					400,
184→				);
185→			}
186→			if (!body.targetFileType) {
187→				return errorResponse(
188→					"targetFileType is required",
189→					"INVALID_REQUEST",
190→					400,
191→				);
192→			}
193→			if (!body.provider) {
194→				return errorResponse("provider is required", "INVALID_REQUEST", 400);
195→			}
196→
197→			const remediationId = this.remediationJobManager.submitJob(body);
198→
199→			return okResponse({
200→				remediationId,
201→				sseUrl: `/api/remediation/${remediationId}/progress`,
202→				status: "queued",
203→			});
204→		} catch (err: unknown) {
205→			console.error("[RemediationRoutes] Error executing remediation:", err);
206→			return internalErrorResponse("Failed to start remediation execution");
207→		}
208→	}
