  77→
  78→export function RemediateTab({
  79→	evaluationId,
  80→	evaluationData,
  81→	selectedIssueKeys,
  82→	issueKeyMap,
  83→	onRemoveIssue,
  84→	onClearAll,
  85→}: RemediateTabProps) {
  86→	const api = useEvaluationApi();
  87→	const providerDetection = useProviderDetection();
  88→
  89→	const [phase, setPhase] = useState<Phase>("config");
  90→	const [targetFileType, setTargetFileType] = useState<
  91→		"AGENTS.md" | "CLAUDE.md"
  92→	>("AGENTS.md");
  93→	const [selectedProvider, setSelectedProvider] =
  94→		useState<ProviderName>("claude");
  95→	const [isExecuting, setIsExecuting] = useState(false);
  96→	const [showConfirmModal, setShowConfirmModal] = useState(false);
  97→	const [executeError, setExecuteError] = useState<string | null>(null);
  98→
  99→	// SSE state
 100→	const [sseUrl, setSseUrl] = useState<string | null>(null);
 101→	const [remediationId, setRemediationId] = useState<string | null>(null);
 102→	const [progressState, setProgressState] = useState<IRemediationProgressState>(
 103→		{
 104→			status: "queued",
 105→			logs: [],
 106→		},
 107→	);
