 109→	// Results state
 110→	const [result, setResult] = useState<RemediationResult | null>(null);
 111→
 112→	// Legacy prompt generation state
 113→	const [isGenerating, setIsGenerating] = useState(false);
 114→	const [generateError, setGenerateError] = useState<string | null>(null);
 115→	const [prompts, setPrompts] = useState<RemediationPromptsResponse | null>(
 116→		null,
 117→	);
 118→
 119→	// Detect providers on mount
 120→	useEffect(() => {
 121→		if (providerDetection.status === "idle") {
 122→			providerDetection.detectProviders();
 123→		}
 124→	}, [providerDetection]);
 125→
 126→	// Restore existing remediation on mount / evaluationId change
 127→	useEffect(() => {
 128→		if (!evaluationId) return;
 129→
 130→		let cancelled = false;
 131→
 132→		async function loadExistingRemediation() {
 133→			const data = await api.getRemediationForEvaluation(evaluationId!);
 134→			if (cancelled || !data) return;
 135→
 136→			if (data.status === "completed") {
 137→				const restoredResult = toRemediationResult(data);
 138→				if (restoredResult) {
 139→					setRemediationId(data.id);
 140→					setResult(restoredResult);
 141→					setPhase("results");
 142→				}
 143→			} else if (data.status === "running" || data.status === "queued") {
 144→				setRemediationId(data.id);
 145→				setSseUrl(
 146→					`${window.location.origin}/api/remediation/${data.id}/progress`,
 147→				);
 148→				setProgressState({
 149→					status: data.status as "queued" | "running",
 150→					logs: [],
 151→				});
 152→				setPhase("progress");
 153→			}
 154→			// "failed" or anything else: stay in config phase
 155→		}
 156→
 157→		loadExistingRemediation();
 158→
 159→		return () => {
 160→			cancelled = true;
 161→		};
 162→	}, [evaluationId, api]);
 163→
 164→	// Available providers for the selector
 165→	const availableProviders = useMemo(() => {
 166→		const providers: ProviderStatus[] = [];
 167→		for (const p of providerDetection.providers.values()) {
 168→			if (p.available && p.name !== "random") {
 169→				providers.push(p);
 170→			}
 171→		}
 172→		return providers;
 173→	}, [providerDetection.providers]);
 174→
 175→	// Resolve selected issue keys to actual issues, split by type
 176→	const { errorEntries, suggestionEntries } = useMemo(() => {
 177→		const errors: { key: string; issue: Issue }[] = [];
 178→		const suggestions: { key: string; issue: Issue }[] = [];
 179→
 180→		for (const key of selectedIssueKeys) {
 181→			const issue = issueKeyMap.get(key);
 182→			if (!issue) continue;
 183→			const type = getIssueType(issue);
 184→			if (type === "error") {
 185→				errors.push({ key, issue });
 186→			} else {
 187→				suggestions.push({ key, issue });
 188→			}
 189→		}
 190→
 191→		errors.sort(
 192→			(a, b) => getIssueSeverity(b.issue) - getIssueSeverity(a.issue),
 193→		);
 194→		const impactOrder: Record<string, number> = {
 195→			High: 0,
 196→			Medium: 1,
 197→			Low: 2,
 198→		};
 199→		suggestions.sort(
 200→			(a, b) =>
 201→				(impactOrder[a.issue.impactLevel ?? "Low"] ?? 2) -
 202→				(impactOrder[b.issue.impactLevel ?? "Low"] ?? 2),
 203→		);
 204→
 205→		return { errorEntries: errors, suggestionEntries: suggestions };
 206→	}, [selectedIssueKeys, issueKeyMap]);
 207→
 208→	const totalSelected = errorEntries.length + suggestionEntries.length;
 209→
 210→	// SSE message handler
 211→	const handleSSEMessage = useCallback(
 212→		// biome-ignore lint/suspicious/noExplicitAny: SSE event data varies by type
 213→		(event: any) => {
 214→			const timestamp = new Date().toISOString();
 215→
 216→			switch (event.type) {
 217→				case "remediation.started":
 218→					setProgressState((prev) => ({
 219→						...prev,
 220→						status: "running",
 221→						logs: [...prev.logs, { timestamp, message: "Remediation started" }],
 222→					}));
 223→					break;
 224→
 225→				case "remediation.progress": {
 226→					const d = event.data ?? {};
 227→					setProgressState((prev) => ({
 228→						...prev,
 229→						...(d.errorCount !== undefined && {
 230→							errorCount: d.errorCount as number,
 231→						}),
 232→						...(d.suggestionCount !== undefined && {
 233→							suggestionCount: d.suggestionCount as number,
 234→						}),
 235→						...(d.totalBatches !== undefined && {
 236→							totalBatches: d.totalBatches as number,
 237→						}),
 238→						...(d.completedBatches !== undefined && {
 239→							completedBatches: d.completedBatches as number,
 240→						}),
 241→						...(d.phase !== undefined && {
 242→							currentPhase: d.phase as "errors" | "suggestions",
 243→						}),
 244→						...(d.runningTotalCostUsd !== undefined && {
 245→							runningTotalCostUsd: d.runningTotalCostUsd as number,
 246→						}),
 247→						...(d.runningTotalDurationMs !== undefined && {
 248→							runningTotalDurationMs: d.runningTotalDurationMs as number,
 249→						}),
 250→						...(d.runningTotalInputTokens !== undefined && {
 251→							runningTotalInputTokens: d.runningTotalInputTokens as number,
 252→						}),
 253→						...(d.runningTotalOutputTokens !== undefined && {
 254→							runningTotalOutputTokens: d.runningTotalOutputTokens as number,
 255→						}),
 256→					}));
 257→					break;
 258→				}
 259→
 260→				case "remediation.step.started": {
 261→					const bi = event.data?.batchInfo as
 262→						| { batchNumber: number; totalBatches: number }
 263→						| undefined;
 264→					const batchLabel = bi
 265→						? ` (batch ${bi.batchNumber}/${bi.totalBatches})`
 266→						: "";
 267→					const issueSummaries = event.data?.issuesSummary as
 268→						| string[]
 269→						| undefined;
 270→					setProgressState((prev) => ({
 271→						...prev,
 272→						currentStep: event.data?.step,
 273→						batchInfo: bi,
 274→						...(issueSummaries && { currentBatchIssues: issueSummaries }),
 275→						logs: [
 276→							...prev.logs,
 277→							{
 278→								timestamp,
 279→								message: `Step started: ${event.data?.step}${batchLabel}`,
 280→							},
 281→						],
 282→					}));
 283→					break;
 284→				}
 285→
 286→				case "remediation.step.completed": {
 287→					const bi2 = event.data?.batchInfo as
 288→						| { batchNumber: number; totalBatches: number }
 289→						| undefined;
 290→					const batchLabel2 = bi2
 291→						? ` (batch ${bi2.batchNumber}/${bi2.totalBatches})`
 292→						: "";
 293→					const step = event.data?.step as string | undefined;
 294→					const batchDurationMs = event.data?.batchDurationMs as
 295→						| number
 296→						| undefined;
 297→					const batchCostUsd = event.data?.batchCostUsd as number | undefined;
 298→					const batchInputTokens = event.data?.batchInputTokens as
 299→						| number
 300→						| undefined;
 301→					const batchOutputTokens = event.data?.batchOutputTokens as
 302→						| number
 303→						| undefined;
 304→
 305→					const hasBatchStats =
 306→						batchDurationMs !== undefined && batchCostUsd !== undefined;
 307→					let logMessage = `Step completed: ${step}${batchLabel2}`;
 308→					if (hasBatchStats) {
 309→						const phaseName =
 310→							step === "executing_error_fix"
 311→								? "Error fix"
 312→								: "Suggestion enrich";
 313→						const label = bi2
 314→							? `${phaseName} batch ${bi2.batchNumber}/${bi2.totalBatches}`
 315→							: phaseName;
 316→						logMessage = `${label} completed: ${Math.round(batchDurationMs / 1000)}s, $${batchCostUsd.toFixed(4)}`;
 317→					}
 318→
 319→					setProgressState((prev) => ({
 320→						...prev,
 321→						batchInfo: undefined,
 322→						currentBatchIssues: undefined,
 323→						...(hasBatchStats && {
 324→							lastBatchStats: {
 325→								durationMs: batchDurationMs!,
 326→								costUsd: batchCostUsd!,
 327→								inputTokens: batchInputTokens ?? 0,
 328→								outputTokens: batchOutputTokens ?? 0,
 329→							},
 330→						}),
 331→						logs: [...prev.logs, { timestamp, message: logMessage }],
 332→					}));
 333→					break;
 334→				}
 335→
 336→				case "remediation.completed": {
 337→					const remResult = event.data?.result as RemediationResult | undefined;
 338→					setProgressState((prev) => ({
 339→						...prev,
 340→						status: "completed",
 341→						result: remResult,
 342→						logs: [
 343→							...prev.logs,
 344→							{ timestamp, message: "Remediation completed" },
 345→						],
 346→					}));
 347→					if (remResult) {
 348→						setResult(remResult);
 349→					}
 350→					setPhase("results");
 351→					setSseUrl(null);
 352→					break;
 353→				}
 354→
 355→				case "remediation.failed":
 356→					setProgressState((prev) => ({
 357→						...prev,
 358→						status: "failed",
 359→						error: event.data?.error,
 360→						logs: [
 361→							...prev.logs,
 362→							{
 363→								timestamp,
 364→								message: `Failed: ${event.data?.error?.message || "Unknown error"}`,
 365→							},
 366→						],
 367→					}));
 368→					setExecuteError(event.data?.error?.message || "Remediation failed");
 369→					setPhase("config");
 370→					setSseUrl(null);
 371→					break;
 372→			}
 373→		},
 374→		[],
 375→	);
 376→
 377→	useSSE({
 378→		url: sseUrl,
 379→		onMessage: handleSSEMessage,
 380→	});
 381→
 382→	// Execute remediation
 383→	const handleExecute = useCallback(async () => {
 384→		if (!evaluationId || totalSelected === 0) return;
 385→
 386→		setIsExecuting(true);
 387→		setExecuteError(null);
 388→		setPrompts(null);
 389→
 390→		try {
 391→			const issues = [
 392→				...errorEntries.map((e) => e.issue),
 393→				...suggestionEntries.map((e) => e.issue),
 394→			];
