 894→					const issueTitle =
 895→						issue.title || issue.problem || issue.description || issue.category;
 896→
 897→					return (
 898→						<div
 899→							key={key}
 900→							className="flex items-center gap-2 py-1 px-1 rounded hover:bg-slate-700/30 group"
