 904→							/>
 905→							<div className="flex-shrink-0 w-[72px]">
 906→								{issue.issueType === "error" ? (
 907→									<span className={getSeverityColor(issue.severity)}>
 908→										{severityLevel.charAt(0).toUpperCase() +
 909→											severityLevel.slice(1)}
 910→									</span>
 911→								) : (
 912→									<span className={getImpactBadgeClass(issue.impactLevel)}>
