 929→							>
 930→								<svg
 931→									className="h-4 w-4"
 932→									fill="none"
 933→									viewBox="0 0 24 24"
 934→									stroke="currentColor"
 935→								>
 936→									<path
 937→										strokeLinecap="round"
 938→										strokeLinejoin="round"
 939→										strokeWidth={2}
 940→										d="M6 18L18 6M6 6l12 12"
 941→									/>
 942→								</svg>
 943→							</button>
 944→						</div>
 945→					);
 946→				})}
 947→			</div>
 948→		</div>
