1052→/**
1053→ * Get action summaries relevant to a specific file path.
1054→ */
1055→function getFileSummaries(
1056→	filePath: string,
1057→	result: RemediationResult,
1058→): RemediationAction[] {
1059→	if (!result.summary?.parsed) return [];
1060→
1061→	const allActions = [
1062→		...result.summary.errorFixActions,
1063→		...result.summary.suggestionEnrichActions,
1064→	];
1065→
1066→	return allActions.filter(
1067→		(a) => a.file && a.status !== "skipped" && filePath.endsWith(a.file),
1068→	);
1069→}
