1027→function ActionSummarySection({
1028→	summary,
1029→}: {
1030→	summary: NonNullable<RemediationResult["summary"]>;
1031→}) {
1032→	const allActions = [
1033→		...summary.errorFixActions,
1034→		...summary.suggestionEnrichActions,
1035→	];
1036→
1037→	const groupedActions = useMemo(() => {
1038→		const groups = new Map<string, RemediationAction[]>();
1039→		for (const action of allActions) {
1040→			const key = action.issueTitle ?? "Other";
1041→			const existing = groups.get(key);
1042→			if (existing) existing.push(action);
1043→			else groups.set(key, [action]);
1044→		}
1045→		return groups;
1046→	}, [summary.errorFixActions, summary.suggestionEnrichActions]);
1047→
1048→	return (
1049→		<div className="card">
1050→			<div className="flex items-center justify-between mb-3">
1051→				<h3 className="text-subheading text-slate-200">Action Summary</h3>
1052→				<span className="text-caption">
1053→					{summary.addressedCount} addressed
1054→					{summary.skippedCount > 0 && (
1055→						<span className="text-slate-500">
1056→							, {summary.skippedCount} skipped
1057→						</span>
1058→					)}
1059→				</span>
1060→			</div>
1061→			<div className="space-y-3">
1062→				{[...groupedActions.entries()].map(([issueTitle, actions]) => (
1063→					<div key={issueTitle}>
1064→						<div className="flex items-center justify-between mb-1 px-1">
1065→							<span className="text-sm font-medium text-slate-300">
1066→								{getGroupDisplayName(issueTitle)}
1067→							</span>
1068→							<span className="text-xs text-slate-500">
1069→								{actions.length} {actions.length === 1 ? "action" : "actions"}
1070→							</span>
1071→						</div>
1072→						<div className="pl-4 border-l border-slate-700/50 space-y-1">
1073→							{actions.map((action) => (
1074→								<div
1075→									key={`${action.issueIndex}-${action.status}`}
1076→									className="flex items-start gap-2 py-1 px-1"
1077→								>
1078→									{action.status === "skipped" ? (
1079→										<span className="text-slate-500 flex-shrink-0 mt-0.5">
1080→											<svg
1081→												className="w-4 h-4"
1082→												fill="none"
1083→												viewBox="0 0 24 24"
1084→												stroke="currentColor"
1085→											>
1086→												<path
1087→													strokeLinecap="round"
1088→													strokeLinejoin="round"
1089→													strokeWidth={2}
1090→													d="M20 12H4"
1091→												/>
1092→											</svg>
1093→										</span>
1094→									) : (
1095→										<span className="text-green-400 flex-shrink-0 mt-0.5">
1096→											<svg
1097→												className="w-4 h-4"
1098→												fill="none"
1099→												viewBox="0 0 24 24"
1100→												stroke="currentColor"
1101→											>
1102→												<path
1103→													strokeLinecap="round"
1104→													strokeLinejoin="round"
1105→													strokeWidth={2}
1106→													d="M5 13l4 4L19 7"
1107→												/>
1108→											</svg>
1109→										</span>
1110→									)}
1111→									<span className="text-sm text-slate-300 flex-1">
1112→										{action.summary}
1113→									</span>
1114→									{action.file && (
1115→										<span className="text-xs text-slate-500 font-mono flex-shrink-0">
1116→											{action.file}
1117→										</span>
1118→									)}
1119→								</div>
1120→							))}
