1129→/**
1130→ * Get action summaries relevant to a specific file path.
1131→ */
1132→function getFileSummaries(
1133→	filePath: string,
1134→	result: RemediationResult,
1135→): RemediationAction[] {
1136→	if (!result.summary?.parsed) return [];
1137→
1138→	const allActions = [
1139→		...result.summary.errorFixActions,
1140→		...result.summary.suggestionEnrichActions,
1141→	];
1142→
1143→	return allActions.filter(
1144→		(a) => a.file && a.status !== "skipped" && filePath.endsWith(a.file),
1145→	);
1146→}
