   597→// Type guard for StructuredError
   598→export function isStructuredError(error: unknown): error is StructuredError {
   599→	return (
   600→		typeof error === "object" &&
   601→		error !== null &&
   602→		"message" in error &&
   603→		"category" in error &&
   604→		"severity" in error &&
   605→		"timestamp" in error &&
   606→		"retryable" in error
   607→	);
   608→}
   609→
   610→// Convert impact level to numeric severity for sorting
   611→// High: 7-10, Medium: 5-6, Low: 1-4
   612→export function impactToSeverity(
   613→	impactLevel: "High" | "Medium" | "Low",
   614→): number {
   615→	if (impactLevel === "High") return 9;
   616→	if (impactLevel === "Medium") return 6;
   617→	return 3;
   618→}
   619→
   620→// Helper to get sortable severity value from any issue
   621→export function getIssueSeverity(issue: Issue): number {
   622→	if (issue.issueType === "error") {
   623→		return issue.severity;
   624→	}
   625→	return impactToSeverity(issue.impactLevel);
   626→}
