   440→// Parse evaluator result string to extract issues
   441→export function parseEvaluatorResult(resultString: string): Issue[] {
   442→	try {
   443→		// First, try to parse as JSON directly
   444→		const parsed = JSON.parse(resultString);
   445→
   446→		// Handle unified format: {perFileIssues: {...}, crossFileIssues: [...]}
   447→		if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
   448→			const allIssues: Issue[] = [];
   449→
   450→			// Extract per-file issues
   451→			if (parsed.perFileIssues && typeof parsed.perFileIssues === "object") {
   452→				for (const fileIssues of Object.values(parsed.perFileIssues)) {
   453→					if (Array.isArray(fileIssues)) {
   454→						allIssues.push(...(fileIssues as Issue[]));
   455→					}
   456→				}
   457→			}
   458→
   459→			// Extract cross-file issues
   460→			if (Array.isArray(parsed.crossFileIssues)) {
   461→				allIssues.push(...parsed.crossFileIssues);
   462→			}
   463→
   464→			return allIssues;
   465→		}
   466→
   467→		// Handle array format directly
   468→		if (Array.isArray(parsed)) {
   469→			return parsed as Issue[];
   470→		}
   471→
   472→		return [];
   473→	} catch {
   474→		// If JSON parse fails, try to find JSON array in the result
   475→		// The result might contain markdown or other text before the JSON array
   476→		try {
   477→			const jsonMatch = resultString.match(/\[[\s\S]*\]/);
   478→			if (!jsonMatch) {
   479→				return [];
   480→			}
   481→
   482→			const issues = JSON.parse(jsonMatch[0]) as Issue[];
   483→			return Array.isArray(issues) ? issues : [];
   484→		} catch {
   485→			return [];
   486→		}
   487→	}
   488→}
