   539→// Issue type helpers
   540→
   541→/**
   542→ * Evaluators categorized as "suggestions" (opportunities for improvement).
   543→ * All other evaluators are categorized as "errors" (problems to fix).
   544→ */
   545→const SUGGESTION_EVALUATORS = new Set([
   546→	"11-subdirectory-coverage",
   547→	"12-context-gaps",
   548→]);
   549→
   550→/**
   551→ * Get the issue type for a given issue, with backward compatibility.
   552→ * If the issue has an explicit issueType, use that.
   553→ * Otherwise, infer from the evaluator name.
   554→ */
   555→export function getIssueType(issue: Issue): "error" | "suggestion" {
   556→	// Use explicit issueType if available
   557→	if (issue.issueType) {
   558→		return issue.issueType;
   559→	}
   560→	// Infer from evaluator name for backward compatibility
   561→	if (issue.evaluatorName && SUGGESTION_EVALUATORS.has(issue.evaluatorName)) {
   562→		return "suggestion";
   563→	}
   564→	return "error";
   565→}
   566→
   567→/**
   568→ * Determines if an issue affects multiple files or has no specific file
   569→ */
   570→export function isCrossFileIssue(issue: Issue): boolean {
   571→	if (issue.affectedFiles && issue.affectedFiles.length > 1) return true;
   572→	if (issue.isMultiFile) return true;
   573→
   574→	if (Array.isArray(issue.location)) {
   575→		const files = issue.location
   576→			.map((loc) => loc.file)
   577→			.filter((f): f is string => f !== undefined);
   578→		if (new Set(files).size > 1) return true;
   579→	}
   580→
   581→	return false;
   582→}
   583→
   584→/**
   585→ * Gets the primary file path for an issue (null for cross-file issues)
   586→ */
   587→export function getIssueFile(issue: Issue): string | null {
   588→	if (isCrossFileIssue(issue)) return null;
   589→
   590→	if (!Array.isArray(issue.location) && issue.location.file) {
   591→		return issue.location.file;
   592→	}
   593→
   594→	if (Array.isArray(issue.location) && issue.location[0]?.file) {
   595→		return issue.location[0].file;
   596→	}
   597→
   598→	if (issue.affectedFiles && issue.affectedFiles.length === 1) {
   599→		return issue.affectedFiles[0];
   600→	}
   601→
   602→	return null;
   603→}
