   605→/**
   606→ * Gets the maximum severity from a group of issues
   607→ */
   608→export function getMaxIssueSeverity(issues: Issue[]): number {
   609→	if (issues.length === 0) return 0;
   610→	return Math.max(...issues.map(getIssueSeverity));
   611→}
