    33→/**
    34→ * Browser modal for viewing context files (AGENTS.md, CLAUDE.md, copilot-instructions.md).
    35→ * Displays a list on the left with markdown preview on the right.
    36→ */
    37→export const ContextFilesBrowserModal: React.FC<
    38→	ContextFilesBrowserModalProps
    39→> = ({ isOpen, onClose, contextFiles, filterType }) => {
    40→	// Filter context files by type if filterType is provided
    41→	const filteredContextFiles = useMemo(() => {
    42→		if (!filterType) return contextFiles;
    43→		// "claude-code" shows both claude and rules files
    44→		if (filterType === "claude-code") {
    45→			return contextFiles.filter(
    46→				(file) => file.type === "claude" || file.type === "rules",
    47→			);
    48→		}
    49→		return contextFiles.filter((file) => file.type === filterType);
    50→	}, [contextFiles, filterType]);
    51→
    52→	// Transform context files to generic content items, sorted alphabetically by path
    53→	const items: ContentItem[] = useMemo(() => {
    54→		// Sort alphabetically by path
    55→		const sortedFiles = [...filteredContextFiles].sort((a, b) =>
    56→			a.path.localeCompare(b.path),
    57→		);
    58→
    59→		return sortedFiles.map((file) => {
    60→			// Add globs info to description for rules files
    61→			let description = file.summary;
    62→			if (file.type === "rules" && file.globs) {
    63→				description = description
    64→					? `Applies to: ${file.globs}\n\n${description}`
    65→					: `Applies to: ${file.globs}`;
    66→			}
    67→
    68→			return {
    69→				id: file.path,
    70→				title: file.path.split("/").pop() || file.path,
    71→				subtitle: file.path,
    72→				description,
    73→				content: file.content
    74→					? stripMarkdownFrontmatter(file.content)
    75→					: undefined,
    76→				badge: getTypeLabel(file.type),
    77→			};
    78→		});
    79→	}, [filteredContextFiles]);
    80→
    81→	// Dynamic title based on filter type
    82→	const modalTitle = useMemo(() => {
    83→		if (!filterType) return "Context Files Browser";
    84→		if (filterType === "claude-code") return "Claude Code Browser";
    85→		return `${getTypeLabel(filterType)} Browser`;
    86→	}, [filterType]);
    87→
    88→	return (
    89→		<ContentBrowserModal
    90→			isOpen={isOpen}
    91→			onClose={onClose}
    92→			items={items}
    93→			title={modalTitle}
    94→			icon={
    95→				<svg
    96→					className="w-4 h-4 text-slate-300"
    97→					fill="none"
    98→					viewBox="0 0 24 24"
    99→					stroke="currentColor"
   100→				>
   101→					<path
   102→						strokeLinecap="round"
   103→						strokeLinejoin="round"
   104→						strokeWidth={2}
   105→						d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"
   106→					/>
   107→				</svg>
   108→			}
   109→			searchPlaceholder="Search context files..."
   110→			emptySearchText="No context files found"
   111→			selectPromptText="Select a context file to view its content"
   112→			noContentText="Content not available"
   113→			noContentSubtext="Re-run evaluation to load file content"
   114→		/>
