     1→import React, { useMemo } from "react";
     2→import { stripMarkdownFrontmatter } from "../../lib/markdown-utils";
     3→import type { IContextFile } from "../../types/evaluation";
     4→import { ContentBrowserModal, type ContentItem } from "./ContentBrowserModal";
     5→
     6→interface ContextFilesBrowserModalProps {
     7→	/** Whether the modal is open */
     8→	isOpen: boolean;
     9→	/** Callback when the modal should close */
    10→	onClose: () => void;
    11→	/** Context files to display */
    12→	contextFiles: IContextFile[];
    13→	/** Optional filter to show only files of a specific type. "claude-code" shows both claude and rules files. "cursor" shows cursor rules. */
    14→	filterType?:
    15→		| "agents"
    16→		| "claude"
    17→		| "copilot"
    18→		| "rules"
    19→		| "claude-code"
    20→		| "cursor-rules"
    21→		| "skills";
    22→}
    23→
    24→/**
    25→ * Get human-readable label for context file type
    26→ */
    27→function getTypeLabel(
    28→	type: "agents" | "claude" | "copilot" | "rules" | "cursor-rules" | "skills",
    29→): string {
    30→	switch (type) {
    31→		case "agents":
    32→			return "AGENTS.md";
    33→		case "claude":
    34→			return "CLAUDE.md";
    35→		case "rules":
    36→			return "Rules";
    37→		case "copilot":
    38→			return "Copilot";
    39→		case "cursor-rules":
    40→			return "Cursor Rule";
    41→		case "skills":
    42→			return "Skill";
    43→	}
    44→}
    45→
    46→/**
    47→ * Browser modal for viewing context files (AGENTS.md, CLAUDE.md, copilot-instructions.md).
    48→ * Displays a list on the left with markdown preview on the right.
    49→ */
    50→export const ContextFilesBrowserModal: React.FC<
    51→	ContextFilesBrowserModalProps
    52→> = ({ isOpen, onClose, contextFiles, filterType }) => {
    53→	// Filter context files by type if filterType is provided
    54→	const filteredContextFiles = useMemo(() => {
    55→		if (!filterType) return contextFiles;
    56→		// "claude-code" shows both claude and rules files
    57→		if (filterType === "claude-code") {
    58→			return contextFiles.filter(
    59→				(file) => file.type === "claude" || file.type === "rules",
    60→			);
    61→		}
    62→		return contextFiles.filter((file) => file.type === filterType);
    63→	}, [contextFiles, filterType]);
    64→
    65→	// Transform context files to generic content items, sorted alphabetically by path
    66→	const items: ContentItem[] = useMemo(() => {
    67→		// Sort alphabetically by path
    68→		const sortedFiles = [...filteredContextFiles].sort((a, b) =>
    69→			a.path.localeCompare(b.path),
    70→		);
    71→
    72→		return sortedFiles.map((file) => {
    73→			// Add globs/description info for rules files
    74→			let description = file.summary;
    75→			if (
    76→				(file.type === "rules" || file.type === "cursor-rules") &&
    77→				file.globs
    78→			) {
    79→				description = description
    80→					? `Applies to: ${file.globs}\n\n${description}`
    81→					: `Applies to: ${file.globs}`;
    82→			}
    83→			if (file.type === "cursor-rules" && file.description) {
    84→				const descLine = `Description: ${file.description}`;
    85→				description = description ? `${descLine}\n${description}` : descLine;
    86→			}
    87→
    88→			return {
    89→				id: file.path,
    90→				title: file.path.split("/").pop() || file.path,
    91→				subtitle: file.path,
    92→				description,
    93→				content: file.content
    94→					? stripMarkdownFrontmatter(file.content)
    95→					: undefined,
    96→				badge: getTypeLabel(file.type),
    97→			};
    98→		});
    99→	}, [filteredContextFiles]);
   100→
   101→	// Dynamic title based on filter type
   102→	const modalTitle = useMemo(() => {
   103→		if (!filterType) return "Context Files Browser";
   104→		if (filterType === "claude-code") return "Claude Code Browser";
   105→		return `${getTypeLabel(filterType)} Browser`;
   106→	}, [filterType]);
   107→
   108→	return (
   109→		<ContentBrowserModal
   110→			isOpen={isOpen}
   111→			onClose={onClose}
   112→			items={items}
   113→			title={modalTitle}
   114→			icon={
   115→				<svg
   116→					className="w-4 h-4 text-slate-300"
   117→					fill="none"
   118→					viewBox="0 0 24 24"
   119→					stroke="currentColor"
   120→				>
   121→					<path
   122→						strokeLinecap="round"
   123→						strokeLinejoin="round"
   124→						strokeWidth={2}
   125→						d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"
   126→					/>
   127→				</svg>
   128→			}
   129→			searchPlaceholder="Search context files..."
   130→			emptySearchText="No context files found"
   131→			selectPromptText="Select a context file to view its content"
   132→			noContentText="Content not available"
   133→			noContentSubtext="Re-run evaluation to load file content"
   134→		/>
   135→	);
   136→};
