    73→export interface IContextScore {
    74→	score: number;
    75→	grade: ContextScoreGrade;
    76→	summary: string;
    77→	breakdown?: IContextScoreBreakdown; // Optional - may be missing in some evaluation results
    78→	recommendations: string[];
    79→	explanation: string; // User-friendly one-liner explaining the score
