   123→export const ContextTreeView: React.FC<ContextTreeViewProps> = ({
   124→	contextFiles,
   125→	skills,
   126→	linkedDocs,
   127→	onFileClick,
   128→}) => {
   129→	const treeNodes = useMemo(
   130→		() => buildContextTree(contextFiles, skills, linkedDocs),
   131→		[contextFiles, skills, linkedDocs],
   132→	);
   133→
   134→	const defaultExpandedIds = useMemo(
   135→		() => getAllBranchIds(treeNodes),
   136→		[treeNodes],
   137→	);
   138→
   139→	const collection = useMemo(
   140→		() =>
   141→			createTreeCollection<ContextTreeNode>({
   142→				rootNode: { id: "root", name: "root", children: treeNodes },
   143→				nodeToValue: (node) => node.id,
   144→				nodeToString: (node) => node.name,
   145→				nodeToChildren: (node) => node.children ?? [],
   146→			}),
   147→		[treeNodes],
   148→	);
   149→
   150→	if (treeNodes.length === 0) {
   151→		return (
   152→			<div className="p-12 text-center">
   153→				<p className="text-sm text-slate-400">
   154→					No context files to display in tree view.
   155→				</p>
   156→			</div>
   157→		);
   158→	}
   159→
   160→	return (
   161→		<div className="p-2">
   162→			<TreeView.Root
   163→				collection={collection}
   164→				defaultExpandedValue={defaultExpandedIds}
   165→			>
   166→				<TreeView.Tree>
