   655→/**
   656→ * Full context scoring pipeline
   657→ */
   658→export async function computeFullContextScore(
   659→	issues: Issue[],
   660→	filesFound: number,
   661→	options: {
   662→		verbose?: boolean;
   663→		filesExpected?: number;
   664→		projectContext?: IProjectContext;
   665→		timeout?: number;
   666→	} = {},
   667→): Promise<IContextScore> {
   668→	const { verbose = false, filesExpected, projectContext, timeout } = options;
   669→
   670→	// Compute breakdown
   671→	const breakdown = computeContextScore({
   672→		issues,
   673→		filesFound,
   674→		filesExpected,
   675→		projectContext,
   676→	});
   677→
   678→	// Calculate score
   679→	const score = calculateScore(breakdown);
   680→	const grade = getGradeFromScore(score);
   681→
   682→	// Generate AI explanation
   683→	const { summary, recommendations } = await generateScoreExplanation(
   684→		score,
   685→		breakdown,
   686→		issues,
   687→		{ verbose, timeout },
   688→	);
   689→
   690→	// Generate user-friendly explanation
   691→	const explanation = generateExplanation(
   692→		score,
   693→		grade,
   694→		breakdown.setupBonus.total,
   695→		breakdown.issuePenalty.penalty,
   696→		breakdown.context.agentsFileCount,
   697→	);
   698→
   699→	return {
   700→		score,
   701→		grade,
   702→		summary,
   703→		breakdown,
   704→		recommendations,
   705→		explanation,
   706→	};
   707→}
