   427→/**
   428→ * Deduplicate context files (AGENTS.md and CLAUDE.md) in the same directory.
   429→ * If both files exist in the same directory with identical content (after trimming whitespace),
   430→ * keep only AGENTS.md to avoid redundant evaluation.
   431→ * @param files - List of absolute file paths
   432→ * @param verbose - If true, log debug information about deduplication
   433→ * @returns Deduplicated list of file paths
   434→ */
   435→async function deduplicateContextFiles(
   436→	files: string[],
   437→	verbose?: boolean,
   438→): Promise<string[]> {
   439→	// Group files by directory
   440→	const filesByDir = new Map<string, string[]>();
   441→	for (const file of files) {
   442→		const dir = dirname(file);
   443→		if (!filesByDir.has(dir)) {
   444→			filesByDir.set(dir, []);
   445→		}
   446→		filesByDir.get(dir)!.push(file);
   447→	}
   448→
   449→	const result: string[] = [];
   450→
   451→	for (const [dir, filesInDir] of filesByDir) {
   452→		// If only one file in directory, keep it
   453→		if (filesInDir.length === 1) {
   454→			result.push(filesInDir[0]!);
   455→			continue;
   456→		}
