     1→import { basename, dirname, relative } from "node:path";
     2→
     3→export interface ColocatedPair {
     4→	directory: string;
     5→	agentsPath: string;
     6→	claudePath: string;
     7→}
     8→
     9→/**
    10→ * Identify directories where both AGENTS.md and CLAUDE.md coexist with different content.
    11→ * These pairs have already survived deduplication (identical content and cross-references removed),
    12→ * so any remaining pairs contain genuinely different content.
    13→ *
    14→ * @param files - Absolute paths to discovered context files (post-deduplication)
    15→ * @param baseDir - Base directory for computing relative paths
    16→ * @returns Array of colocated pairs with relative paths
    17→ */
    18→export function identifyColocatedPairs(
    19→	files: string[],
    20→	baseDir: string,
    21→): ColocatedPair[] {
    22→	const filesByDir = new Map<string, string[]>();
    23→	for (const file of files) {
    24→		const dir = dirname(file);
    25→		if (!filesByDir.has(dir)) {
    26→			filesByDir.set(dir, []);
    27→		}
    28→		filesByDir.get(dir)!.push(file);
    29→	}
    30→
    31→	const pairs: ColocatedPair[] = [];
    32→
    33→	for (const [dir, filesInDir] of filesByDir) {
    34→		const agentsFile = filesInDir.find(
    35→			(f) => basename(f).toLowerCase() === "agents.md",
    36→		);
    37→		const claudeFile = filesInDir.find(
    38→			(f) => basename(f).toLowerCase() === "claude.md",
    39→		);
    40→
    41→		if (agentsFile && claudeFile) {
    42→			const relDir = relative(baseDir, dir) || ".";
    43→			pairs.push({
    44→				directory: relDir,
    45→				agentsPath: relative(baseDir, agentsFile),
    46→				claudePath: relative(baseDir, claudeFile),
    47→			});
    48→		}
    49→	}
    50→
    51→	return pairs;
    52→}
    53→
    54→/**
    55→ * Filter out CLAUDE.md entries from a file list for directories that have a colocated pair.
    56→ * AGENTS.md becomes the sole source of truth for evaluation.
    57→ *
    58→ * @param files - Absolute paths to context files
    59→ * @param pairs - Colocated pairs identified by identifyColocatedPairs
    60→ * @param baseDir - Base directory for computing relative paths
    61→ * @returns Filtered list of absolute paths with colocated CLAUDE.md files removed
    62→ */
    63→export function filterConsolidatedPaths(
    64→	files: string[],
    65→	pairs: ColocatedPair[],
    66→	baseDir: string,
    67→): string[] {
    68→	if (pairs.length === 0) return files;
    69→
    70→	const claudeRelPaths = new Set(pairs.map((p) => p.claudePath));
    71→
    72→	return files.filter((f) => {
    73→		const relPath = relative(baseDir, f);
    74→		return !claudeRelPaths.has(relPath);
    75→	});
    76→}
