 1→import { readFile, writeFile } from "node:fs/promises";
 2→import { join } from "node:path";
 3→import type { ColocatedPair } from "@shared/file-system/colocated-file-consolidator";
 4→import { isFileReference } from "@shared/file-system/file-reference-detector";
 5→
 6→export interface ConsolidationResult {
 7→	directory: string;
 8→	agentsPath: string;
 9→	claudePath: string;
10→	skipped: boolean;
11→	reason?: string;
12→}
13→
14→/**
15→ * Consolidate colocated AGENTS.md/CLAUDE.md pairs during remediation.
16→ * For each pair:
17→ * 1. Skip if CLAUDE.md is already `@AGENTS.md`
18→ * 2. Append CLAUDE.md content to AGENTS.md with a separator
19→ * 3. Rewrite CLAUDE.md to `@AGENTS.md`
20→ */
21→export async function consolidateColocatedFiles(
22→	workDir: string,
23→	pairs: ColocatedPair[],
24→): Promise<ConsolidationResult[]> {
25→	const results: ConsolidationResult[] = [];
26→
27→	for (const pair of pairs) {
28→		const agentsAbsPath = join(workDir, pair.agentsPath);
29→		const claudeAbsPath = join(workDir, pair.claudePath);
30→
31→		try {
32→			const claudeContent = await readFile(claudeAbsPath, "utf-8");
33→
34→			// Skip if CLAUDE.md is already a reference pointer
35→			const refResult = isFileReference(claudeContent);
36→			if (refResult.isReference) {
37→				results.push({
38→					...pair,
39→					skipped: true,
40→					reason: `CLAUDE.md is already a reference to ${refResult.referencedFile}`,
41→				});
42→				continue;
43→			}
44→
45→			// Read AGENTS.md content
46→			const agentsContent = await readFile(agentsAbsPath, "utf-8");
47→
48→			// Append CLAUDE.md content to AGENTS.md
49→			const mergedContent = `${agentsContent.trimEnd()}\n\n<!-- Merged from CLAUDE.md -->\n\n${claudeContent.trimStart()}`;
50→			await writeFile(agentsAbsPath, mergedContent, "utf-8");
51→
52→			// Rewrite CLAUDE.md to reference pointer
53→			await writeFile(claudeAbsPath, "@AGENTS.md\n", "utf-8");
54→
55→			results.push({
56→				...pair,
57→				skipped: false,
58→			});
59→		} catch (error) {
60→			results.push({
61→				...pair,
62→				skipped: true,
63→				reason: `Error: ${error instanceof Error ? error.message : String(error)}`,
64→			});
65→		}
66→	}
67→
68→	return results;
69→}
