533→function isCopilotInstructionsFile(filePath: string): boolean {
534→	const filename = basename(filePath).toLowerCase();
535→
536→	// Original pattern: copilot-instructions.md
537→	if (filename === "copilot-instructions.md") {
538→		return true;
539→	}
540→
541→	// New pattern: *.instructions.md in .github/instructions/ directory
542→	if (
543→		filename.endsWith(".instructions.md") &&
544→		filePath.includes(".github/instructions/")
545→	) {
546→		return true;
547→	}
548→
549→	return false;
550→}
