 37→	/**
 38→	 * Invoke GitHub Copilot CLI with a prompt
 39→	 */
 40→	async invoke(
 41→		prompt: string,
 42→		options: IProviderInvokeOptions = {},
 43→	): Promise<IProviderResponse> {
 44→		const { verbose = false, timeout = DEFAULT_TIMEOUT_MS, cwd } = options;
 45→
 46→		// Guard against prompts that exceed OS argument size limits
 47→		const promptBytes = new TextEncoder().encode(prompt).length;
 48→		if (promptBytes > MAX_PROMPT_ARG_BYTES) {
 49→			throw new Error(
 50→				`Prompt too large for GitHub Copilot CLI argument (${(promptBytes / 1024).toFixed(0)} KB). ` +
 51→					`The Copilot CLI requires the prompt as a -p argument value, which is limited by OS ARG_MAX. ` +
 52→					`Maximum supported: ${(MAX_PROMPT_ARG_BYTES / 1024).toFixed(0)} KB. ` +
 53→					`Consider using --agent claude instead for large evaluations.`,
 54→			);
 55→		}
 56→
 57→		// GitHub Copilot CLI command format: copilot -p "<prompt>" -s --no-ask-user --no-custom-instructions --allow-all-tools
 58→		// -p <text>: Execute prompt in non-interactive mode (prompt MUST be the argument value)
 59→		// -s / --silent: Output only the agent response (no stats), cleaner for parsing
 60→		// --no-ask-user: Agent works autonomously without asking questions
 61→		// --no-custom-instructions: Prevent loading target repo's AGENTS.md (which could interfere with evaluator prompts)
 62→		// --allow-all-tools: Allow all tools without confirmation
 63→		const args = [
 64→			"-p",
 65→			prompt,
 66→			"-s",
 67→			"--no-ask-user",
 68→			"--no-custom-instructions",
 69→			"--allow-all-tools",
 70→		];
 71→
 72→		if (verbose) {
 73→			console.log(`\n[GitHub Copilot] Starting API call...`);
 74→			console.log(`[GitHub Copilot] Prompt length: ${prompt.length} chars`);
 75→			console.log(
 76→				`[GitHub Copilot] Timeout: ${timeout}ms (${(timeout / 1000).toFixed(1)}s)`,
 77→			);
 78→			if (cwd) {
 79→				console.log(`[GitHub Copilot] Working directory: ${cwd}`);
 80→			}
 81→			console.log(
 82→				`[GitHub Copilot] Command: copilot -p <prompt> -s --no-ask-user --no-custom-instructions --allow-all-tools`,
 83→			);
 84→			console.log(`[GitHub Copilot] Spawning process...`);
 85→		}
 86→
 87→		const startTime = Date.now();
 88→
 89→		const proc = Bun.spawn(["copilot", ...args], {
 90→			stdin: "ignore",
 91→			stdout: "pipe",
 92→			stderr: "pipe",
 93→			env: process.env,
 94→			cwd: cwd || process.cwd(),
 95→		});
 96→
 97→		if (verbose) {
 98→			console.log(`[GitHub Copilot] Process spawned (PID: ${proc.pid})`);
 99→			console.log(`[GitHub Copilot] Waiting for response...`);
100→		}
101→
102→		// Progress indicator for long operations
103→		let progressInterval: ReturnType<typeof setInterval> | undefined;
104→		if (verbose) {
105→			progressInterval = setInterval(() => {
106→				const elapsed = Date.now() - startTime;
107→				const remaining = timeout - elapsed;
108→				console.log(
109→					`[GitHub Copilot] Still waiting... ${(elapsed / 1000).toFixed(1)}s elapsed, ${(remaining / 1000).toFixed(1)}s remaining`,
110→				);
111→			}, 5000);
112→		}
113→
114→		// Set up timeout
115→		const timeoutPromise = this.createTimeoutPromise<[string, string, number]>(
116→			timeout,
117→			() => {
118→				if (progressInterval) clearInterval(progressInterval);
119→				proc.kill();
120→			},
121→			startTime,
122→		);
123→
124→		try {
125→			const [stdout, stderr, exitCode] = await Promise.race([
126→				Promise.all([
127→					new Response(proc.stdout).text(),
128→					new Response(proc.stderr).text(),
129→					proc.exited,
130→				]),
131→				timeoutPromise,
132→			]);
133→
134→			if (progressInterval) clearInterval(progressInterval);
135→
136→			const elapsed = Date.now() - startTime;
137→			if (verbose) {
138→				console.log(
139→					`[GitHub Copilot] Process exited with code ${exitCode} after ${(elapsed / 1000).toFixed(1)}s`,
140→				);
141→				console.log(
142→					`[GitHub Copilot] stdout size: ${(stdout.length / 1024).toFixed(1)} KB`,
143→				);
144→				if (stderr) {
145→					console.log(
146→						`[GitHub Copilot] stderr size: ${(stderr.length / 1024).toFixed(1)} KB`,
147→					);
148→				}
149→
150→				// Show first 200 chars of stdout for debugging
151→				if (stdout.length > 0) {
152→					const preview = stdout.substring(0, 200).replace(/\n/g, "\\n");
153→					console.log(
154→						`[GitHub Copilot] stdout preview: ${preview}${stdout.length > 200 ? "..." : ""}`,
155→					);
156→				}
157→
158→				// Show stderr content if present
159→				if (stderr && stderr.length > 0) {
160→					const stderrPreview = stderr.substring(0, 500).replace(/\n/g, "\\n");
161→					console.log(
162→						`[GitHub Copilot] stderr content: ${stderrPreview}${stderr.length > 500 ? "..." : ""}`,
163→					);
164→				}
165→			}
166→
167→			if (exitCode !== 0) {
168→				const exitCodeExplanation = this.getExitCodeExplanation(exitCode);
169→				const errorDetails = [
170→					`GitHub Copilot CLI exited with code ${exitCode}${exitCodeExplanation}`,
171→					stderr ? `stderr: ${stderr.trim()}` : null,
172→					stdout
173→						? `stdout preview: ${stdout.substring(0, 500)}`
174→						: "(no stdout)",
175→				]
176→					.filter(Boolean)
177→					.join("\n");
178→				throw new Error(errorDetails);
179→			}
180→
181→			// GitHub Copilot returns raw text, not JSON
182→			// Measure duration via timestamps since no metrics are available
183→			const duration_ms = Date.now() - startTime;
184→
185→			if (verbose) {
186→				console.log(
187→					`[GitHub Copilot] ✓ Received response (${stdout.length} chars) in ${duration_ms}ms`,
188→				);
189→			}
190→
191→			return {
192→				result: stdout,
193→				duration_ms,
194→				// Cost and usage metrics are not available from GitHub Copilot CLI
195→			};
196→		} catch (err) {
197→			if (progressInterval) clearInterval(progressInterval);
198→
199→			const message = err instanceof Error ? err.message : String(err);
200→			if (message.includes("ENOENT")) {
201→				throw new Error(
202→					`GitHub Copilot CLI not found. Is 'copilot' installed and in your PATH? Original error: ${message}`,
203→				);
204→			} else if (message.includes("EACCES")) {
205→				throw new Error(
206→					`Permission denied when running GitHub Copilot CLI. Check file permissions. Original error: ${message}`,
207→				);
208→			} else if (message.includes("E2BIG")) {
209→				throw new Error(
210→					`Prompt too large for GitHub Copilot CLI. The prompt exceeds OS argument size limits. Original error: ${message}`,
211→				);
212→			}
213→			throw err;
214→		}
215→	}
