217→	/**
218→	 * Normalize response - GitHub Copilot returns raw text, not JSON
219→	 * This method is not used since we return the raw stdout directly
220→	 */
221→	protected normalizeResponse(parsed: unknown): IProviderResponse {
222→		// GitHub Copilot doesn't return JSON, but if it somehow does,
223→		// handle it gracefully
224→		if (typeof parsed === "string") {
225→			return { result: parsed };
226→		}
227→		if (
228→			typeof parsed === "object" &&
229→			parsed !== null &&
230→			"result" in parsed &&
231→			typeof (parsed as { result: unknown }).result === "string"
232→		) {
233→			return { result: (parsed as { result: string }).result };
234→		}
235→		return { result: JSON.stringify(parsed) };
236→	}
237→}
