291→/**
292→ * Discover and summarize linked documentation from AGENTS.md files.
293→ * Finds all .md files linked from the provided AGENTS.md files,
294→ * reads their content, and generates AI summaries.
295→ *
296→ * @param agentsFiles - Absolute paths to AGENTS.md/CLAUDE.md files
297→ * @param baseDir - Repository base directory
298→ * @param options - Discovery options
299→ * @returns Discovery result with summarized docs
300→ */
301→export async function discoverLinkedDocs(
302→	agentsFiles: string[],
303→	baseDir: string,
304→	options: IDocDiscoveryOptions,
305→): Promise<ILinkedDocsResult> {
306→	const {
307→		provider,
308→		verbose = false,
309→		maxDocs = 30,
310→		maxContentLength = 8000,
311→		concurrency = 2,
312→	} = options;
313→
314→	const allLinks: IExtractedLink[] = [];
315→	const unresolvedLinks: string[] = [];
316→
317→	// Step 1: Extract links from all AGENTS.md files
318→	for (const agentsFile of agentsFiles) {
319→		try {
320→			const content = await readFile(agentsFile, "utf-8");
321→			const links = extractMarkdownLinks(content, agentsFile);
322→
323→			if (verbose && links.length > 0) {
324→				console.log(
325→					`[DocsFinder] Found ${links.length} link(s) in ${getRelativePath(agentsFile, baseDir)}`,
326→				);
327→			}
328→
329→			allLinks.push(...links);
330→		} catch (error) {
331→			if (verbose) {
332→				console.log(`[DocsFinder] Error reading ${agentsFile}:`, error);
333→			}
334→		}
335→	}
336→
337→	// Step 2: Deduplicate links (same target from different sources)
338→	const uniqueLinks = new Map<string, IExtractedLink>();
339→	for (const link of allLinks) {
340→		// Keep the first occurrence (typically from root AGENTS.md)
341→		if (!uniqueLinks.has(link.absolutePath)) {
342→			uniqueLinks.set(link.absolutePath, link);
343→		}
344→	}
345→
346→	const deduplicatedLinks = Array.from(uniqueLinks.values());
347→	const totalLinksFound = deduplicatedLinks.length;
348→
349→	if (verbose) {
350→		console.log(
351→			`[DocsFinder] ${totalLinksFound} unique linked doc(s) found after deduplication`,
352→		);
353→	}
354→
355→	// Step 3: Limit to maxDocs (prioritize links from root AGENTS.md)
356→	// Links are already ordered by source file, so we just take the first N
357→	const linksToProcess = deduplicatedLinks.slice(0, maxDocs);
358→
359→	if (verbose && totalLinksFound > maxDocs) {
360→		console.log(
361→			`[DocsFinder] Limiting to ${maxDocs} docs (${totalLinksFound - maxDocs} skipped)`,
362→		);
363→	}
364→
365→	// Step 4: Read and summarize each linked doc
366→	const docs: ILinkedDocSummary[] = [];
367→
368→	const summarizeLink = async (link: IExtractedLink): Promise<void> => {
369→		const content = await readFileWithLimit(
370→			link.absolutePath,
371→			maxContentLength,
372→		);
373→
374→		if (content === null) {
375→			unresolvedLinks.push(link.rawPath);
376→			if (verbose) {
377→				console.log(`[DocsFinder] File not found: ${link.rawPath}`);
378→			}
379→			return;
380→		}
381→
382→		const relativePath = getRelativePath(link.absolutePath, baseDir);
383→		const linkedFrom = getRelativePath(link.sourcePath, baseDir);
384→
385→		if (verbose) {
386→			console.log(`[DocsFinder] Summarizing: ${relativePath}`);
387→		}
388→
389→		const summary = await summarizeDocFile(
390→			relativePath,
391→			content,
392→			provider,
393→			options.timeout,
394→		);
395→
396→		docs.push({
397→			path: relativePath,
398→			summary,
399→			linkedFrom,
400→			content, // Include content for preview in browser modal
401→		});
402→	};
403→
404→	// Process links with concurrency control
405→	await runWithConcurrencyLimit(linksToProcess, concurrency, (link) =>
406→		summarizeLink(link),
407→	);
408→
409→	if (verbose) {
410→		console.log(
411→			`[DocsFinder] Successfully summarized ${docs.length} doc(s), ${unresolvedLinks.length} unresolved`,
412→		);
413→	}
414→
415→	return {
416→		docs,
417→		totalLinksFound,
418→		unresolvedLinks,
419→	};
420→}
