    10→/**
    11→ * Represents an extracted Markdown link
    12→ */
    13→export interface IExtractedLink {
    14→	/** Raw link target as written in the source */
    15→	rawPath: string;
    16→	/** Resolved absolute path */
    17→	absolutePath: string;
    18→	/** Link text/label */
    19→	linkText: string;
    20→	/** Source file containing the link */
    21→	sourcePath: string;
    22→}
    23→
    24→/**
    25→ * Options for linked docs discovery
    26→ */
    27→export interface IDocDiscoveryOptions {
    28→	/** AI provider for summarization */
    29→	provider: IAIProvider;
    30→	/** Enable verbose logging */
    31→	verbose?: boolean;
    32→	/** Maximum number of docs to summarize (default: 30) */
    33→	maxDocs?: number;
    34→	/** Maximum content length per file before truncation (default: 8000) */
    35→	maxContentLength?: number;
    36→	/** Concurrency for summarization calls (default: 3) */
    37→	concurrency?: number;
    38→	/** Timeout in milliseconds for AI provider calls (default: 60000) */
    39→	timeout?: number;
    40→}
    41→
    42→/**
    43→ * Result of linked docs discovery
    44→ */
    45→export interface ILinkedDocsResult {
    46→	/** Discovered and summarized documentation */
    47→	docs: ILinkedDocSummary[];
    48→	/** Total links found before filtering */
    49→	totalLinksFound: number;
    50→	/** Links that couldn't be resolved (file not found) */
    51→	unresolvedLinks: string[];
    52→}
    53→
    54→// Regex patterns for Markdown links
    55→// Inline: [text](path/to/file.md) or [text](path/to/file.md#anchor)
    56→const INLINE_LINK_REGEX = /\[([^\]]+)\]\(([^)]+\.md(?:#[^)]*)?)\)/gi;
    57→
    58→// Reference definition: [ref]: path/to/file.md
    59→const REFERENCE_DEF_REGEX = /^\[([^\]]+)\]:\s*(\S+\.md(?:#\S*)?)\s*$/gim;
    60→
    61→/**
    62→ * Check if a path is an external URL
    63→ */
    64→function isExternalUrl(path: string): boolean {
    65→	return (
    66→		path.startsWith("http://") ||
    67→		path.startsWith("https://") ||
    68→		path.startsWith("//")
    69→	);
    70→}
    71→
    72→/**
    73→ * Check if a path is an anchor-only link
    74→ */
    75→function isAnchorOnly(path: string): boolean {
    76→	return path.startsWith("#");
    77→}
    78→
    79→/**
    80→ * Check if a path is a self-reference to AGENTS.md, CLAUDE.md, copilot-instructions.md,
    81→ * or *.instructions.md files in .github/instructions/
    82→ */
    83→function isSelfReference(path: string): boolean {
    84→	const filename = path.split("/").pop()?.split("#")[0]?.toLowerCase() ?? "";
    85→
    86→	// Original patterns
    87→	if (
    88→		filename === "agents.md" ||
    89→		filename === "claude.md" ||
    90→		filename === "copilot-instructions.md"
    91→	) {
    92→		return true;
    93→	}
    94→
    95→	// New pattern: *.instructions.md in .github/instructions/ directory
    96→	if (
    97→		filename.endsWith(".instructions.md") &&
    98→		path.includes(".github/instructions/")
    99→	) {
   100→		return true;
   101→	}
   102→
   103→	return false;
   104→}
   105→
   106→/**
   107→ * Remove anchor fragment from path
   108→ */
   109→function removeAnchor(path: string): string {
   110→	return path.split("#")[0] ?? path;
   111→}
   112→
   113→/**
   114→ * Check if a path is a skill sub-file that should be excluded from linked docs.
   115→ * Skills are structured as: <root>/skills/<skill-name>/SKILL.md
   116→ * Only the top-level SKILL.md is relevant; nested files are progressive-disclosure refs.
   117→ *
   118→ * Keeps:    .../skills/<skill-name>/SKILL.md
   119→ * Discards: .../skills/<skill-name>/anything-else.md
   120→ *           .../skills/<skill-name>/subdir/file.md
   121→ */
   122→function isSkillsSubFile(absolutePath: string): boolean {
   123→	const normalized = absolutePath.replace(/\\/g, "/");
   124→	const match = normalized.match(/\/skills\/[^/]+\/(.+)$/);
   125→	if (!match) return false;
   126→	return match[1] !== "SKILL.md";
   127→}
   128→
   129→/**
   130→ * Extract Markdown links to .md files from content.
   131→ * Handles: [text](path.md), [text](path.md#anchor), [ref]: path.md
   132→ * Excludes: external URLs, anchor-only links, self-references
   133→ *
   134→ * @param content - Markdown content to parse
   135→ * @param sourcePath - Absolute path to the source file
   136→ * @returns Array of extracted links with resolved paths
   137→ */
   138→export function extractMarkdownLinks(
   139→	content: string,
   140→	sourcePath: string,
   141→): IExtractedLink[] {
   142→	const links: IExtractedLink[] = [];
   143→	const sourceDir = dirname(sourcePath);
   144→	const seenPaths = new Set<string>();
   145→
   146→	// Process inline links: [text](path.md)
   147→	let match: RegExpExecArray | null;
   148→	INLINE_LINK_REGEX.lastIndex = 0;
   149→	while ((match = INLINE_LINK_REGEX.exec(content)) !== null) {
   150→		const linkText = match[1] ?? "";
   151→		const rawPath = match[2] ?? "";
   152→
   153→		if (!rawPath || isExternalUrl(rawPath) || isAnchorOnly(rawPath)) {
   154→			continue;
   155→		}
   156→
   157→		const cleanPath = removeAnchor(rawPath);
   158→
   159→		if (isSelfReference(cleanPath)) {
   160→			continue;
   161→		}
   162→
   163→		// Resolve relative path
   164→		const absolutePath = isAbsolute(cleanPath)
   165→			? cleanPath
   166→			: resolve(sourceDir, cleanPath);
   167→
   168→		if (isSkillsSubFile(absolutePath)) {
   169→			continue;
   170→		}
   171→
   172→		// Deduplicate
   173→		if (seenPaths.has(absolutePath)) {
   174→			continue;
   175→		}
   176→		seenPaths.add(absolutePath);
   177→
   178→		links.push({
   179→			rawPath: cleanPath,
   180→			absolutePath,
   181→			linkText,
   182→			sourcePath,
   183→		});
   184→	}
   185→
   186→	// Process reference definitions: [ref]: path.md
   187→	REFERENCE_DEF_REGEX.lastIndex = 0;
   188→	while ((match = REFERENCE_DEF_REGEX.exec(content)) !== null) {
   189→		const linkText = match[1] ?? "";
   190→		const rawPath = match[2] ?? "";
   191→
   192→		if (!rawPath || isExternalUrl(rawPath) || isAnchorOnly(rawPath)) {
   193→			continue;
   194→		}
   195→
   196→		const cleanPath = removeAnchor(rawPath);
   197→
   198→		if (isSelfReference(cleanPath)) {
   199→			continue;
   200→		}
   201→
   202→		const absolutePath = isAbsolute(cleanPath)
   203→			? cleanPath
   204→			: resolve(sourceDir, cleanPath);
   205→
   206→		if (isSkillsSubFile(absolutePath)) {
   207→			continue;
   208→		}
   209→
   210→		if (seenPaths.has(absolutePath)) {
   211→			continue;
   212→		}
   213→		seenPaths.add(absolutePath);
   214→
   215→		links.push({
   216→			rawPath: cleanPath,
   217→			absolutePath,
   218→			linkText,
   219→			sourcePath,
   220→		});
   221→	}
   222→
   223→	return links;
   224→}
