488→/**
489→ * Build a prompt for single-file evaluation
490→ */
491→export async function buildSingleFilePrompt(
492→	evaluatorPrompt: string,
493→	agentsContent: string,
494→	projectContext: string | undefined,
495→	evaluatorName: string,
496→): Promise<string> {
497→	const category = extractCategory(evaluatorPrompt);
498→	const outputFormatTemplate = await loadOutputFormatTemplate(
499→		category,
500→		evaluatorName,
501→	);
502→	const contextSection = buildProjectContextSection(projectContext);
503→
504→	// Handle empty or missing content
505→	if (isEmptyContent(agentsContent)) {
506→		return `${evaluatorPrompt}\n\n${contextSection}${outputFormatTemplate}\n\n---\n\n${NO_FILE_MESSAGE}${JSON_OUTPUT_REMINDER}`;
507→	}
508→
509→	const numberedContent = addLineNumbers(agentsContent);
510→	return `${evaluatorPrompt}\n\n${contextSection}${outputFormatTemplate}\n\n---\n\n## Context File Content to Evaluate:\n\n\`\`\`markdown\n${numberedContent}\n\`\`\`${JSON_OUTPUT_REMINDER}`;
511→}
512→
513→/**
514→ * Build a combined prompt for multi-file evaluation
515→ */
516→export async function buildMultiFilePrompt(
517→	evaluatorPrompt: string,
518→	files: FileContext[],
519→	projectContext: string | undefined,
520→	evaluatorName: string,
521→): Promise<string> {
522→	const category = extractCategory(evaluatorPrompt);
523→	const outputFormatTemplate = await loadOutputFormatTemplate(
524→		category,
525→		evaluatorName,
526→	);
527→	const contextSection = buildProjectContextSection(projectContext);
528→
529→	// Handle case where all files have empty content (no AGENTS.md files mode)
530→	const allEmpty =
531→		files.length === 0 || files.every((f) => isEmptyContent(f.content));
532→	if (allEmpty) {
533→		return `${evaluatorPrompt}\n\n${contextSection}${outputFormatTemplate}\n\n---\n\n${NO_FILE_MESSAGE}${JSON_OUTPUT_REMINDER}`;
534→	}
535→
536→	const fileBlocks = files
537→		.map((file, index) => formatFileBlockWithSeparators(file, index))
538→		.join("\n\n");
539→
540→	return `${evaluatorPrompt}\n\n${contextSection}${outputFormatTemplate}\n\n---\n\n## Multiple Context Files to Evaluate:\n\n${fileBlocks}${JSON_OUTPUT_REMINDER}`;
541→}
