488→/**
489→ * Build a prompt for single-file evaluation
490→ */
491→export async function buildSingleFilePrompt(
492→	evaluatorPrompt: string,
493→	agentsContent: string,
494→	projectContext: string | undefined,
495→	evaluatorName: string,
496→): Promise<string> {
497→	const category = extractCategory(evaluatorPrompt);
498→	const outputFormatTemplate = await loadOutputFormatTemplate(
499→		category,
500→		evaluatorName,
501→	);
502→	const contextSection = buildProjectContextSection(projectContext);
503→
504→	// Prompt ordering: file content → project context → evaluator template → output format → JSON reminder
505→	// File content and project context are identical across evaluators, so placing them first
506→	// maximizes the shared prefix for Anthropic's prompt caching.
507→
508→	// Handle empty or missing content
509→	if (isEmptyContent(agentsContent)) {
510→		return `${NO_FILE_MESSAGE}\n\n${contextSection}${evaluatorPrompt}\n\n${outputFormatTemplate}${JSON_OUTPUT_REMINDER}`;
511→	}
512→
513→	const numberedContent = addLineNumbers(agentsContent);
514→	return `## Context File Content to Evaluate:\n\n\`\`\`markdown\n${numberedContent}\n\`\`\`\n\n---\n\n${contextSection}${evaluatorPrompt}\n\n${outputFormatTemplate}${JSON_OUTPUT_REMINDER}`;
515→}
