517→/**
518→ * Build a combined prompt for multi-file evaluation
519→ */
520→export async function buildMultiFilePrompt(
521→	evaluatorPrompt: string,
522→	files: FileContext[],
523→	projectContext: string | undefined,
524→	evaluatorName: string,
525→): Promise<string> {
526→	const category = extractCategory(evaluatorPrompt);
527→	const outputFormatTemplate = await loadOutputFormatTemplate(
528→		category,
529→		evaluatorName,
530→	);
531→	const contextSection = buildProjectContextSection(projectContext);
532→
533→	// Prompt ordering: file content → project context → evaluator template → output format → JSON reminder
534→	// File content and project context are identical across evaluators, so placing them first
535→	// maximizes the shared prefix for Anthropic's prompt caching.
536→
537→	// Handle case where all files have empty content (no AGENTS.md files mode)
538→	const allEmpty =
539→		files.length === 0 || files.every((f) => isEmptyContent(f.content));
540→	if (allEmpty) {
541→		return `${NO_FILE_MESSAGE}\n\n${contextSection}${evaluatorPrompt}\n\n${outputFormatTemplate}${JSON_OUTPUT_REMINDER}`;
542→	}
543→
544→	const fileBlocks = files
545→		.map((file, index) => formatFileBlockWithSeparators(file, index))
546→		.join("\n\n");
547→
548→	return `## Multiple Context Files to Evaluate:\n\n${fileBlocks}\n\n---\n\n${contextSection}${evaluatorPrompt}\n\n${outputFormatTemplate}${JSON_OUTPUT_REMINDER}`;
549→}
