 71→func (c *Claude) IsTransientError(out Output, err error) bool {
 72→	if err == nil {
 73→		return false
 74→	}
 75→	combined := out.Stdout + out.Stderr
 76→	transientPatterns := []string{
 77→		"overloaded",
 78→		"rate limit",
 79→		"529",
 80→		"503",
 81→		"ECONNRESET",
 82→		"ETIMEDOUT",
 83→	}
 84→	for _, p := range transientPatterns {
 85→		if strings.Contains(combined, p) {
 86→			return true
 87→		}
 88→	}
 89→	return false
 90→}
