 92→func (c *Claude) Bootstrap() error {
 93→	// On CI, write a config file so Claude Code uses the API key from the
 94→	// environment instead of trying OAuth/Keychain.
 95→	if os.Getenv("CI") == "" {
 96→		fmt.Fprintf(os.Stderr, "[e2e] claude Bootstrap: local mode, skipping (using Keychain auth)\n")
 97→		return nil
 98→	}
 99→	apiKey := os.Getenv("ANTHROPIC_API_KEY")
100→	if apiKey == "" {
101→		fmt.Fprintf(os.Stderr, "[e2e] claude Bootstrap: CI mode but ANTHROPIC_API_KEY not set, skipping\n")
102→		return nil
103→	}
104→	fmt.Fprintf(os.Stderr, "[e2e] claude Bootstrap: CI mode, writing API key to ~/.claude/.claude.json\n")
105→	home, err := os.UserHomeDir()
106→	if err != nil {
107→		return fmt.Errorf("get home dir: %w", err)
108→	}
109→	dir := filepath.Join(home, ".claude")
110→	if err := os.MkdirAll(dir, 0o755); err != nil {
111→		return fmt.Errorf("mkdir %s: %w", dir, err)
112→	}
113→	config := fmt.Sprintf(`{"primaryApiKey":%q,"hasCompletedOnboarding":true}`, apiKey)
114→	path := filepath.Join(dir, ".claude.json")
115→	return os.WriteFile(path, []byte(config), 0o644)
116→}
