118→func (c *Claude) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
119→	cfg := &runConfig{Model: "haiku"}
120→	for _, o := range opts {
121→		o(cfg)
122→	}
123→
124→	env := append(cleanEnv(), "ACCESSIBLE=1", "ENTIRE_TEST_TTY=0")
125→
126→	// On CI (no macOS Keychain), use an isolated config dir so Claude Code
127→	// picks up ANTHROPIC_API_KEY from the environment instead of trying OAuth.
128→	// Locally, we skip CLAUDE_CONFIG_DIR so the Keychain-based auth works.
129→	if os.Getenv("CI") != "" {
130→		configDir, err := isolatedConfigDir()
131→		if err != nil {
132→			return Output{}, fmt.Errorf("create isolated config dir: %w", err)
133→		}
134→		defer os.RemoveAll(configDir)
135→		env = append(env, "CLAUDE_CONFIG_DIR="+configDir)
136→		fmt.Fprintf(os.Stderr, "[e2e] claude RunPrompt: CI mode, using isolated config dir %s\n", configDir)
137→	} else {
138→		fmt.Fprintf(os.Stderr, "[e2e] claude RunPrompt: local mode, using default Keychain auth (no CLAUDE_CONFIG_DIR)\n")
139→	}
140→
141→	args := []string{"-p", prompt, "--model", cfg.Model, "--dangerously-skip-permissions"}
142→	displayArgs := []string{"-p", fmt.Sprintf("%q", prompt), "--model", cfg.Model, "--dangerously-skip-permissions"}
143→	cmd := exec.CommandContext(ctx, "claude", args...)
144→	cmd.Dir = dir
145→	cmd.Stdin = nil
146→	cmd.Env = env
147→	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
148→	cmd.Cancel = func() error {
149→		return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
150→	}
151→	cmd.WaitDelay = 5 * time.Second
152→
153→	var stdout, stderr strings.Builder
154→	cmd.Stdout = &stdout
155→	cmd.Stderr = &stderr
156→
157→	err := cmd.Run()
158→	exitCode := 0
159→	exitErr := &exec.ExitError{}
160→	if errors.As(err, &exitErr) {
161→		exitCode = exitErr.ExitCode()
162→	}
163→
164→	return Output{
165→		Command:  "claude " + strings.Join(displayArgs, " "),
166→		Stdout:   stdout.String(),
167→		Stderr:   stderr.String(),
168→		ExitCode: exitCode,
169→	}, err
170→}
