  1→// Agent Rules template formatter
  2→// Produces imperative instructions suitable for CLAUDE.md and cursor rules
  3→
  4→import type { SessionRow, InsightRow } from './knowledge-base.js';
  5→
  6→function parseMetadata(raw: string | null): Record<string, unknown> {
  7→  if (!raw) return {};
  8→  try {
  9→    const parsed = JSON.parse(raw);
 10→    return typeof parsed === 'object' && parsed !== null ? parsed : {};
 11→  } catch {
 12→    return {};
 13→  }
 14→}
 15→
 16→export function formatAgentRules(sessions: SessionRow[], insights: InsightRow[]): string {
 17→  if (sessions.length === 0) return '# Agent Rules Export\n\n*No sessions selected.*\n';
 18→
 19→  // Compute date range and project name from sessions
 20→  const dates = sessions.flatMap((s) => [s.started_at, s.ended_at]).filter(Boolean) as string[];
 21→  const minDate = dates.length > 0 ? dates.reduce((a, b) => (a < b ? a : b)) : null;
 22→  const maxDate = dates.length > 0 ? dates.reduce((a, b) => (a > b ? a : b)) : null;
 23→  const dateRange = minDate && maxDate ? `${minDate.split('T')[0]} – ${maxDate.split('T')[0]}` : 'all time';
 24→
 25→  // Use the most common project name, or the first one
 26→  const projectNames = sessions.map((s) => s.project_name).filter(Boolean) as string[];
 27→  const projectName = projectNames[0] ?? 'unknown';
 28→
 29→  const lines: string[] = [
 30→    `# Agent Rules Export`,
 31→    `> Generated from ${sessions.length} session${sessions.length !== 1 ? 's' : ''} analyzed by Code Insights`,
 32→    `> Project: ${projectName} | Period: ${dateRange}`,
 33→    '',
 34→  ];
 35→
 36→  if (insights.length === 0) {
 37→    lines.push(
 38→      '> **Note:** No insights found. Run analysis on sessions first to generate rules.',
 39→    );
 40→    return lines.join('\n');
 41→  }
 42→
 43→  // Group all insights by type (cross-session, for a global rules document)
 44→  const byType = new Map<string, InsightRow[]>();
 45→  for (const insight of insights) {
 46→    const list = byType.get(insight.type) ?? [];
 47→    list.push(insight);
 48→    byType.set(insight.type, list);
 49→  }
 50→
 51→  const decisions = byType.get('decision');
 52→  if (decisions && decisions.length > 0) {
 53→    lines.push('## Decisions');
 54→    lines.push('');
 55→    for (const insight of decisions) {
 56→      const meta = parseMetadata(insight.metadata);
 57→      lines.push(`### ${insight.title}`);
 58→      const choice = meta.choice as string | undefined;
 59→      const situation = meta.situation as string | undefined;
 60→      const revisit_when = meta.revisit_when as string | undefined;
 61→      const alternatives = meta.alternatives as Array<{ option?: string; rejected_because?: string } | string> | undefined;
 62→
 63→      if (choice && situation) {
 64→        lines.push(`- USE ${choice} for ${situation}`);
 65→      } else if (choice) {
 66→        lines.push(`- USE ${choice}`);
 67→      } else if (insight.content) {
 68→        // No structured metadata — emit a plain directive from the content
 69→        lines.push(`- ${insight.content}`);
 70→      }
 71→
 72→      if (alternatives && alternatives.length > 0) {
 73→        for (const alt of alternatives) {
 74→          if (typeof alt === 'string') {
 75→            lines.push(`- DO NOT use ${alt}`);
 76→          } else if (alt.option) {
 77→            const reason = alt.rejected_because ? ` because ${alt.rejected_because}` : '';
 78→            lines.push(`- DO NOT use ${alt.option}${reason}`);
 79→          }
 80→        }
 81→      }
 82→
 83→      if (revisit_when) {
 84→        lines.push(`- REVISIT this decision when ${revisit_when}`);
 85→      }
 86→      lines.push('');
 87→    }
 88→  }
 89→
 90→  const learnings = byType.get('learning');
 91→  if (learnings && learnings.length > 0) {
 92→    lines.push('## Learnings');
 93→    lines.push('');
 94→    for (const insight of learnings) {
 95→      const meta = parseMetadata(insight.metadata);
 96→      lines.push(`### ${insight.title}`);
 97→      const applies_when = meta.applies_when as string | undefined;
 98→      const symptom = meta.symptom as string | undefined;
 99→      const root_cause = meta.root_cause as string | undefined;
100→      const takeaway = meta.takeaway as string | undefined;
101→
102→      if (applies_when && symptom && root_cause) {
103→        lines.push(`- WHEN ${applies_when}, be aware that ${symptom} is caused by ${root_cause}`);
104→      } else if (symptom && root_cause) {
105→        lines.push(`- Be aware that ${symptom} is caused by ${root_cause}`);
106→      }
107→
108→      if (takeaway) {
109→        lines.push(`- ${takeaway}`);
110→      } else if (!symptom && !root_cause && insight.content) {
111→        lines.push(`- ${insight.content}`);
112→      }
113→      lines.push('');
114→    }
115→  }
116→
117→  const techniques = byType.get('technique');
118→  if (techniques && techniques.length > 0) {
119→    lines.push('## Techniques');
120→    lines.push('');
121→    for (const insight of techniques) {
122→      const meta = parseMetadata(insight.metadata);
123→      lines.push(`### ${insight.title}`);
124→      const context = meta.context as string | undefined;
125→      const applicability = meta.applicability as string | undefined;
126→
127→      if (context) {
128→        lines.push(`- WHEN ${context}, use this approach:`);
129→      }
130→      if (insight.content) {
131→        // Indent content as a block under the directive
132→        for (const contentLine of insight.content.split('\n')) {
133→          lines.push(`  ${contentLine}`);
134→        }
135→      }
136→      if (applicability) {
137→        lines.push(`- Applicability: ${applicability}`);
138→      }
139→      lines.push('');
140→    }
141→  }
142→
143→  const pqInsights = byType.get('prompt_quality');
144→  if (pqInsights && pqInsights.length > 0) {
145→    const antiPatternLines: string[] = [];
146→    for (const insight of pqInsights) {
147→      const meta = parseMetadata(insight.metadata);
148→      const antiPatterns = meta.antiPatterns as Array<{
149→        name?: string;
150→        description?: string;
151→        fix?: string;
152→      }> | undefined;
153→      if (antiPatterns) {
154→        for (const pattern of antiPatterns) {
155→          const desc = pattern.description ? `: ${pattern.description}` : '';
156→          const fix = pattern.fix ? `. Instead: ${pattern.fix}` : '';
157→          antiPatternLines.push(`- AVOID ${pattern.name ?? 'unknown pattern'}${desc}${fix}`);
158→        }
159→      }
160→    }
161→    if (antiPatternLines.length > 0) {
162→      lines.push('## Prompt Patterns to Avoid');
163→      lines.push('');
164→      lines.push(...antiPatternLines);
165→      lines.push('');
166→    }
167→  }
168→
169→  return lines.join('\n');
170→}
