 20→  if (!workspaceId) {
 21→    console.error("Set BRAIN_WORKSPACE_ID env var to your workspace ID.");
 22→    console.error("Find it in the Brain web UI or the database.");
 23→    process.exit(1);
 24→  }
 25→
 26→  console.log("Brain Init\n──────────\n");
 27→
 28→  // Step 1: Auth
 29→  await setupAuth(serverUrl, workspaceId, gitRoot);
 30→
 31→  // Step 2: .mcp.json
 32→  await setupMcpJson(gitRoot);
 33→
 34→  // Step 3: .claude/settings.json hooks
 35→  await setupClaudeHooks(gitRoot);
 36→
 37→  // Step 4: CLAUDE.md
 38→  await setupClaudeMd(gitRoot);
 39→
 40→  // Step 5: Commands
 41→  await setupCommands(gitRoot);
 42→
 43→  // Step 6: Git hooks
 44→  installGitHooks(gitRoot);
 45→
 46→  console.log(`\nDone. Restart Claude Code to activate.`);
 47→}
