250→// Step 3: .claude/settings.json hooks
251→// ---------------------------------------------------------------------------
252→
253→type HookEntry = { type: string; command?: string; prompt?: string };
254→type SettingsHookGroup = { matcher?: string; hooks: HookEntry[] };
255→
256→async function setupClaudeHooks(gitRoot: string): Promise<void> {
257→  const claudeDir = join(gitRoot, ".claude");
258→  if (!existsSync(claudeDir)) mkdirSync(claudeDir, { recursive: true });
259→
260→  const settingsPath = join(claudeDir, "settings.json");
261→  const file = Bun.file(settingsPath);
262→  let settings: Record<string, unknown> = {};
263→
264→  if (await file.exists()) {
265→    try {
266→      settings = await file.json();
267→    } catch {
268→      // Corrupted — start fresh
269→    }
270→  }
271→
272→  const hooks = (settings.hooks ?? {}) as Record<string, SettingsHookGroup[]>;
273→  let added = 0;
274→
275→  for (const [event, hookDefs] of Object.entries(BRAIN_HOOKS)) {
276→    hooks[event] ??= [];
277→
278→    const hasBrain = hooks[event].some((group) =>
279→      group.hooks?.some(
280→        (h) => h.command?.startsWith("brain ") || h.prompt?.includes("Brain MCP"),
281→      ),
282→    );
283→
284→    if (!hasBrain) {
285→      hooks[event].push({ hooks: hookDefs as HookEntry[] });
286→      added++;
287→    }
288→  }
289→
290→  settings.hooks = hooks;
291→  await Bun.write(settingsPath, JSON.stringify(settings, null, 2) + "\n");
292→  console.log(`✓ Hooks: .claude/settings.json updated (${added} hooks added)`);
293→}
