299→const MARKER_START = "<!-- brain-plugin-start -->";
300→const MARKER_END = "<!-- brain-plugin-end -->";
301→
302→async function setupClaudeMd(gitRoot: string): Promise<void> {
303→  const claudeMdPath = join(gitRoot, "CLAUDE.md");
304→  const file = Bun.file(claudeMdPath);
305→  let content = "";
306→
307→  if (await file.exists()) {
308→    content = await file.text();
309→  }
310→
311→  const brainBlock = `${MARKER_START}\n${BRAIN_CLAUDE_MD}\n${MARKER_END}`;
312→
313→  const startIdx = content.indexOf(MARKER_START);
314→  const endIdx = content.indexOf(MARKER_END);
315→
316→  if (startIdx !== -1 && endIdx !== -1) {
317→    content = content.slice(0, startIdx) + brainBlock + content.slice(endIdx + MARKER_END.length);
318→  } else {
319→    const separator = content.length > 0 && !content.endsWith("\n\n") ? "\n\n" : "";
320→    content = content + separator + brainBlock + "\n";
321→  }
322→
323→  await Bun.write(claudeMdPath, content);
324→  console.log("✓ CLAUDE.md: Brain plugin instructions added");
325→}
