329→// ---------------------------------------------------------------------------
330→
331→export function installGitHooks(gitRoot?: string): void {
332→  const root = gitRoot ?? findGitRoot(process.cwd());
333→  if (!root) {
334→    console.log("  No .git directory found — skipping git hook installation.");
335→    return;
336→  }
337→
338→  const hooksDir = join(root, ".git", "hooks");
339→  if (!existsSync(hooksDir)) mkdirSync(hooksDir, { recursive: true });
340→
341→  const preCommitPath = join(hooksDir, "pre-commit");
342→  const postCommitPath = join(hooksDir, "post-commit");
343→  const preCommitScript = `#!/bin/sh
344→# Brain pre-commit hook: check for task completion and unlogged decisions
345→brain check-commit
346→`;
347→
348→  if (!existsSync(preCommitPath)) {
349→    Bun.writeSync(Bun.openSync(preCommitPath, "w"), preCommitScript);
350→    chmodSync(preCommitPath, 0o755);
351→    console.log("✓ Git: pre-commit hook installed");
352→  } else {
353→    console.log("✓ Git: pre-commit hook already exists");
354→  }
355→
356→  // Remove legacy Brain post-commit hook
357→  if (existsSync(postCommitPath)) {
358→    const postCommitContent = Bun.file(postCommitPath).textSync();
359→    const isBrainManaged =
360→      postCommitContent.includes("Brain post-commit hook") &&
361→      postCommitContent.includes("brain log-commit");
362→    if (isBrainManaged) {
363→      unlinkSync(postCommitPath);
364→      console.log("  Removed legacy Brain post-commit hook");
365→    }
366→  }
367→}
