369→async function setupCommands(gitRoot: string): Promise<void> {
370→  const commandsDir = join(gitRoot, ".claude", "commands");
371→  if (!existsSync(commandsDir)) mkdirSync(commandsDir, { recursive: true });
372→
373→  let count = 0;
374→  for (const [filename, content] of Object.entries(BRAIN_COMMANDS)) {
375→    await Bun.write(join(commandsDir, filename), content + "\n");
376→    count++;
377→  }
378→
379→  console.log(`✓ Commands: ${count} slash commands installed to .claude/commands/`);
380→}
