  1→// Synthesis prompts for the Reflect/Patterns feature.
  2→// These prompts receive pre-aggregated facet data and produce cross-session narratives.
  3→// LLMs synthesize — they don't count. All counting is done in code before calling these.
  4→//
  5→// CANONICAL_FRICTION_CATEGORIES is imported but not interpolated into synthesis prompts;
  6→// it's used by extraction prompts in prompts.ts. Kept here for future use if synthesis
  7→// prompts need category hints.
  8→
  9→import { CANONICAL_FRICTION_CATEGORIES } from './prompts.js';
