233→async function setupMcpJson(gitRoot: string): Promise<void> {
234→  const mcpPath = join(gitRoot, ".mcp.json");
235→  const file = Bun.file(mcpPath);
236→  let mcp: { mcpServers: Record<string, unknown> } = { mcpServers: {} };
237→
238→  if (await file.exists()) {
239→    try {
240→      mcp = await file.json();
241→      mcp.mcpServers ??= {};
242→    } catch {
243→      // Corrupted file — overwrite
244→    }
245→  }
246→
247→  mcp.mcpServers.brain = { command: "brain", args: ["mcp"] };
248→  await Bun.write(mcpPath, JSON.stringify(mcp, null, 2) + "\n");
249→  console.log("✓ MCP: .mcp.json updated");
