334→export function installGitHooks(gitRoot?: string): void {
335→  const root = gitRoot ?? findGitRoot(process.cwd());
336→  if (!root) {
337→    console.log("  No .git directory found — skipping git hook installation.");
338→    return;
339→  }
340→
341→  const hooksDir = join(root, ".git", "hooks");
342→  if (!existsSync(hooksDir)) mkdirSync(hooksDir, { recursive: true });
343→
344→  const preCommitPath = join(hooksDir, "pre-commit");
345→  const postCommitPath = join(hooksDir, "post-commit");
346→  const preCommitScript = `#!/bin/sh
347→# Brain pre-commit hook: check for task completion and unlogged decisions
348→brain check-commit
349→`;
350→
351→  if (!existsSync(preCommitPath)) {
352→    Bun.writeSync(Bun.openSync(preCommitPath, "w"), preCommitScript);
353→    chmodSync(preCommitPath, 0o755);
354→    console.log("✓ Git: pre-commit hook installed");
355→  } else {
356→    console.log("✓ Git: pre-commit hook already exists");
357→  }
358→
359→  // Remove legacy Brain post-commit hook
360→  if (existsSync(postCommitPath)) {
361→    const postCommitContent = Bun.file(postCommitPath).textSync();
362→    const isBrainManaged =
363→      postCommitContent.includes("Brain post-commit hook") &&
364→      postCommitContent.includes("brain log-commit");
365→    if (isBrainManaged) {
366→      unlinkSync(postCommitPath);
367→      console.log("  Removed legacy Brain post-commit hook");
368→    }
369→  }
370→}
