350→export function installGitHooks(gitRoot?: string): void {
351→  const root = gitRoot ?? findGitRoot(process.cwd());
352→  if (!root) {
353→    console.log("  No .git directory found — skipping git hook installation.");
354→    return;
355→  }
356→
357→  const hooksDir = join(root, ".git", "hooks");
358→  if (!existsSync(hooksDir)) mkdirSync(hooksDir, { recursive: true });
359→
360→  const preCommitPath = join(hooksDir, "pre-commit");
361→  const postCommitPath = join(hooksDir, "post-commit");
362→  const preCommitScript = `#!/bin/sh
363→# Brain pre-commit hook: check for task completion and unlogged decisions
364→brain check-commit
365→`;
366→
367→  if (!existsSync(preCommitPath)) {
368→    writeFileSync(preCommitPath, preCommitScript, { mode: 0o755 });
369→    console.log("✓ Git: pre-commit hook installed");
370→  } else {
371→    console.log("✓ Git: pre-commit hook already exists");
372→  }
373→
374→  // Remove legacy Brain post-commit hook
375→  if (existsSync(postCommitPath)) {
376→    const postCommitContent = readFileSync(postCommitPath, "utf-8");
377→    const isBrainManaged =
378→      postCommitContent.includes("Brain post-commit hook") &&
379→      postCommitContent.includes("brain log-commit");
380→    if (isBrainManaged) {
381→      unlinkSync(postCommitPath);
382→      console.log("  Removed legacy Brain post-commit hook");
383→    }
384→  }
385→}
