178→function featureTemplate(name: string, id: string, projectId?: string): string {
179→  const lines: string[] = [];
180→  lines.push(`# Brain: Feature — "${name}"`);
181→  lines.push("");
182→  lines.push(`This directory maps to brain feature \`${id}\`.`);
183→
184→  if (projectId) {
185→    lines.push(`Parent project: \`${projectId}\`.`);
186→    lines.push("");
187→    lines.push(
188→      `**On first access**: Call \`get_project_context\` with \`project_id: "${projectId}"\` to load project-level decisions, tasks, and constraints before proceeding.`,
189→    );
190→    lines.push("");
191→    lines.push("When using Brain MCP tools from this directory:");
192→    lines.push(
193→      `- Pass \`project_id: "${projectId}"\` to project-scoped tools (\`get_active_decisions\`, \`get_architecture_constraints\`, \`get_recent_changes\`)`,
194→    );
195→    lines.push(
196→      `- Scope \`create_provisional_decision\` / \`ask_question\` with \`context: { project: "${projectId}", feature: "${id}" }\``,
197→    );
198→  } else {
199→    lines.push("");
200→    lines.push(
201→      `**On first access**: Call \`get_entity_detail\` with \`entity_id: "feature:${id}"\` to resolve the parent project, then call \`get_project_context\` with the resolved project ID to load decisions, tasks, and constraints.`,
202→    );
203→    lines.push("");
204→    lines.push("When using Brain MCP tools from this directory:");
205→    lines.push(
206→      `- Scope \`create_provisional_decision\` / \`ask_question\` with \`context: { feature: "${id}" }\``,
