217→async function writeMapBlock(dir: string, content: string): Promise<void> {
218→  const claudeMdPath = join(dir, "CLAUDE.md");
219→  const file = Bun.file(claudeMdPath);
220→  let existing = "";
221→
222→  if (await file.exists()) {
223→    existing = await file.text();
224→  }
225→
226→  const brainBlock = `${MAP_MARKER_START}\n${content}\n${MAP_MARKER_END}`;
227→
228→  const startIdx = existing.indexOf(MAP_MARKER_START);
229→  const endIdx = existing.indexOf(MAP_MARKER_END);
230→
231→  if (startIdx !== -1 && endIdx !== -1) {
232→    existing =
233→      existing.slice(0, startIdx) +
234→      brainBlock +
235→      existing.slice(endIdx + MAP_MARKER_END.length);
236→  } else {
237→    const separator =
238→      existing.length > 0 && !existing.endsWith("\n\n") ? "\n\n" : "";
239→    existing = existing + separator + brainBlock + "\n";
240→  }
241→
242→  await Bun.write(claudeMdPath, existing);
243→}
