 57→// ---------------------------------------------------------------------------
 58→// Step 1: Auth (OAuth 2.1 PKCE)
 59→// ---------------------------------------------------------------------------
 60→
 61→const DEFAULT_SCOPES = "graph:read graph:reason decision:write task:write observation:write question:write session:write offline_access";
 62→
 63→function base64url(buf: Buffer): string {
 64→  return buf.toString("base64url");
 65→}
 66→
 67→function generatePkce(): { verifier: string; challenge: string } {
 68→  const verifier = base64url(randomBytes(32));
 69→  const challenge = base64url(createHash("sha256").update(verifier).digest());
 70→  return { verifier, challenge };
 71→}
 72→
 73→export async function setupAuth(
 74→  serverUrl: string,
 75→  workspaceId: string,
 76→  gitRoot: string,
 77→  options?: { openUrl?: (url: string) => void },
 78→): Promise<void> {
 79→  const global = await loadGlobalConfig();
 80→  const existing = global?.repos[gitRoot];
 81→  if (existing && existing.workspace === workspaceId && existing.access_token) {
 82→    console.log(`✓ Auth: already configured for ${gitRoot}`);
 83→    return;
 84→  }
 85→
 86→  // 1. Verify workspace exists
 87→  try {
 88→    await BrainHttpClient.listProjects(serverUrl, workspaceId);
 89→  } catch {
 90→    console.error(`Workspace ${workspaceId} not found on ${serverUrl}`);
 91→    process.exit(1);
 92→  }
 93→
 94→  // 2. Dynamic Client Registration
 95→  const dcrRes = await fetch(`${serverUrl}/api/auth/oauth2/register`, {
 96→    method: "POST",
 97→    headers: { "Content-Type": "application/json" },
 98→    body: JSON.stringify({
 99→      client_name: `brain-cli-${workspaceId.slice(0, 8)}`,
100→      redirect_uris: ["http://127.0.0.1/callback"],
101→      grant_types: ["authorization_code", "refresh_token"],
102→      response_types: ["code"],
103→      token_endpoint_auth_method: "none",
104→    }),
105→  });
106→  if (!dcrRes.ok) {
107→    throw new Error(`Client registration failed: ${dcrRes.status} ${await dcrRes.text()}`);
108→  }
109→  const { client_id } = await dcrRes.json() as { client_id: string };
110→
111→  // 3. PKCE
112→  const pkce = generatePkce();
113→  const state = base64url(randomBytes(16));
114→
115→  // 4. Start local callback server
116→  const { promise: codePromise, resolve: resolveCode, reject: rejectCode } = Promise.withResolvers<string>();
117→
118→  const callbackServer = Bun.serve({
119→    port: 0,
120→    hostname: "127.0.0.1",
121→    routes: {
122→      "/callback": (request) => {
123→        const url = new URL(request.url);
124→        const code = url.searchParams.get("code");
125→        const returnedState = url.searchParams.get("state");
126→        const error = url.searchParams.get("error");
127→
128→        if (error) {
129→          rejectCode(new Error(`OAuth error: ${error}`));
130→          return new Response("<html><body><h1>Authentication failed</h1><p>You can close this tab.</p></body></html>", {
131→            headers: { "Content-Type": "text/html" },
132→          });
133→        }
134→        if (returnedState !== state) {
135→          rejectCode(new Error("state mismatch"));
136→          return new Response("<html><body><h1>State mismatch</h1></body></html>", {
137→            headers: { "Content-Type": "text/html" },
138→          });
139→        }
140→        if (!code) {
141→          rejectCode(new Error("no code returned"));
142→          return new Response("<html><body><h1>No authorization code</h1></body></html>", {
143→            headers: { "Content-Type": "text/html" },
144→          });
145→        }
146→
147→        resolveCode(code);
148→        return new Response("<html><body><h1>Authenticated!</h1><p>You can close this tab and return to the terminal.</p></body></html>", {
149→          headers: { "Content-Type": "text/html" },
150→        });
151→      },
152→    },
153→  });
154→
155→  const redirectUri = `http://127.0.0.1:${callbackServer.port}/callback`;
156→
157→  // Update redirect_uris with actual port (re-register)
158→  const dcrUpdateRes = await fetch(`${serverUrl}/api/auth/oauth2/register`, {
159→    method: "POST",
160→    headers: { "Content-Type": "application/json" },
161→    body: JSON.stringify({
162→      client_name: `brain-cli-${workspaceId.slice(0, 8)}`,
163→      redirect_uris: [redirectUri],
164→      grant_types: ["authorization_code", "refresh_token"],
165→      response_types: ["code"],
166→      token_endpoint_auth_method: "none",
167→    }),
168→  });
169→  if (!dcrUpdateRes.ok) {
170→    callbackServer.stop();
171→    throw new Error(`Client re-registration failed: ${dcrUpdateRes.status} ${await dcrUpdateRes.text()}`);
172→  }
173→  const dcrUpdate = await dcrUpdateRes.json() as { client_id: string };
174→  const actualClientId = dcrUpdate.client_id;
175→
176→  // 5. Open browser
177→  const authUrl = new URL(`${serverUrl}/api/auth/oauth2/authorize`);
178→  authUrl.searchParams.set("client_id", actualClientId);
179→  authUrl.searchParams.set("redirect_uri", redirectUri);
180→  authUrl.searchParams.set("response_type", "code");
181→  authUrl.searchParams.set("scope", DEFAULT_SCOPES);
182→  authUrl.searchParams.set("code_challenge", pkce.challenge);
183→  authUrl.searchParams.set("code_challenge_method", "S256");
184→  authUrl.searchParams.set("state", state);
185→  // Pass resource so better-auth issues a JWT access token (not opaque)
186→  authUrl.searchParams.set("resource", serverUrl);
187→
188→  console.log("Opening browser for authentication...");
189→  console.log(`If the browser doesn't open, visit: ${authUrl.toString()}\n`);
190→
191→  const openUrl = options?.openUrl ?? ((url: string) => {
192→    const openCmd = process.platform === "darwin" ? "open" : process.platform === "win32" ? "start" : "xdg-open";
193→    Bun.spawn([openCmd, url], { stdout: "ignore", stderr: "ignore" });
194→  });
195→  openUrl(authUrl.toString());
196→
197→  // 6. Wait for callback
198→  let code: string;
199→  try {
200→    code = await codePromise;
201→  } catch (error) {
202→    callbackServer.stop();
203→    throw error;
204→  }
205→
206→  // 7. Exchange code for tokens
207→  const tokenRes = await fetch(`${serverUrl}/api/auth/oauth2/token`, {
208→    method: "POST",
209→    headers: { "Content-Type": "application/x-www-form-urlencoded" },
210→    body: new URLSearchParams({
211→      grant_type: "authorization_code",
