549→// WaitForSessionMetadata polls until session metadata exists on the checkpoint
550→// branch for the given checkpoint ID and session index, then returns it.
551→// This handles the race where the checkpoint branch advances before session
552→// metadata is fully committed.
553→func WaitForSessionMetadata(t *testing.T, dir string, checkpointID string, sessionIndex int, timeout time.Duration) SessionMetadata {
554→	t.Helper()
555→
556→	path := fmt.Sprintf("%s/%d/metadata.json", CheckpointPath(checkpointID), sessionIndex)
557→	blob := "entire/checkpoints/v1:" + path
558→
559→	deadline := time.Now().Add(timeout)
560→	for time.Now().Before(deadline) {
561→		raw := gitOutputSafe(dir, "show", blob)
562→		if raw != "" {
563→			var meta SessionMetadata
564→			if err := json.Unmarshal([]byte(raw), &meta); err != nil {
565→				t.Fatalf("unmarshal session metadata from %s: %v", blob, err)
566→			}
567→			return meta
568→		}
569→		time.Sleep(500 * time.Millisecond)
570→	}
571→	t.Fatalf("session metadata %s did not appear within %s", blob, timeout)
572→	return SessionMetadata{}
573→}
