501→// CheckpointIDs lists all checkpoint IDs from the tree at the tip of the
502→// checkpoint branch. It parses the two-level directory structure
503→// ({prefix}/{suffix}/metadata.json) and returns the concatenated IDs.
504→func CheckpointIDs(t *testing.T, dir string) []string {
505→	t.Helper()
506→	out := gitOutputSafe(dir, "ls-tree", "-r", "--name-only", "entire/checkpoints/v1")
507→	if out == "" {
508→		return nil
509→	}
510→	seen := map[string]bool{}
511→	var ids []string
512→	for _, line := range strings.Split(strings.TrimSpace(out), "\n") {
513→		// Match {prefix}/{suffix}/metadata.json (top-level, not session-level)
514→		parts := strings.Split(line, "/")
515→		if len(parts) == 3 && parts[2] == "metadata.json" {
516→			id := parts[0] + parts[1]
517→			if !seen[id] {
518→				seen[id] = true
519→				ids = append(ids, id)
520→			}
521→		}
522→	}
523→	return ids
524→}
