562→// WaitForSessionMetadata polls until session metadata exists on the checkpoint
563→// branch for the given checkpoint ID and session index, then returns it.
564→// This handles the race where the checkpoint branch advances before session
565→// metadata is fully committed.
566→func WaitForSessionMetadata(t *testing.T, dir string, checkpointID string, sessionIndex int, timeout time.Duration) SessionMetadata {
567→	t.Helper()
568→
569→	path := fmt.Sprintf("%s/%d/metadata.json", CheckpointPath(checkpointID), sessionIndex)
570→	blob := "entire/checkpoints/v1:" + path
571→
572→	deadline := time.Now().Add(timeout)
573→	for time.Now().Before(deadline) {
574→		raw := gitOutputSafe(dir, "show", blob)
575→		if raw != "" {
576→			var meta SessionMetadata
577→			if err := json.Unmarshal([]byte(raw), &meta); err != nil {
578→				t.Fatalf("unmarshal session metadata from %s: %v", blob, err)
579→			}
580→			return meta
581→		}
582→		time.Sleep(500 * time.Millisecond)
583→	}
584→	t.Fatalf("session metadata %s did not appear within %s", blob, timeout)
585→	return SessionMetadata{}
586→}
