622→// GetCheckpointTrailer extracts the Entire-Checkpoint trailer value from a
623→// code commit. Returns the trimmed trailer value, or an empty string if the
624→// trailer is not present.
625→func GetCheckpointTrailer(t *testing.T, dir string, ref string) string {
626→	t.Helper()
627→
628→	return GitOutput(t, dir, "log", "-1", "--format=%(trailers:key=Entire-Checkpoint,valueonly)", ref)
629→}
