 43→// BuildSystemPrompt composes the full system prompt: basic + memories + skills + project context.
 44→// The basic prompt defaults to the embedded system.md but can be overridden
 45→// by placing a system.md file in the project's .agents directory or the workspace.
 46→// annaHome is the anna home directory (e.g. ~/.anna).
 47→// workspace is the workspace directory (e.g. ~/.anna/workspace) containing SOUL.md, USER.md, system.md.
 48→func BuildSystemPrompt(annaHome, workspace string, cwd ...string) string {
 49→	workDir := ""
 50→	if len(cwd) > 0 {
 51→		workDir = cwd[0]
 52→	}
 53→	projectDir := ""
 54→	if workDir != "" {
 55→		projectDir = filepath.Join(workDir, ".agents")
 56→	}
 57→
 58→	// Basic prompt: project .agents/system.md > workspace system.md > embedded default.
 59→	basic := defaultBasicPrompt
 60→	if content := readFileIfExists(workspace, "system.md"); content != "" {
 61→		basic = content
 62→	}
 63→	if projectDir != "" {
 64→		if content := readFileIfExists(projectDir, "system.md"); content != "" {
 65→			basic = content
 66→		}
 67→	}
 68→
 69→	soul := readFileIfExists(workspace, "SOUL.md")
 70→	user := readFileIfExists(workspace, "USER.md")
 71→
 72→	// Project-level overrides: .agents/SOUL.md and .agents/USER.md take priority.
 73→	if projectDir != "" {
 74→		if content := readFileIfExists(projectDir, "SOUL.md"); content != "" {
 75→			soul = content
 76→		}
 77→		if content := readFileIfExists(projectDir, "USER.md"); content != "" {
 78→			user = content
 79→		}
 80→	}
 81→
 82→	memories := promptMemories{
 83→		Dir:  workspace,
 84→		Soul: promptFile{Path: filepath.Join(workspace, "SOUL.md"), Content: fallback(soul, defaultSoul)},
 85→		User: promptFile{Path: filepath.Join(workspace, "USER.md"), Content: fallback(user, defaultUser)},
 86→	}
 87→
 88→	var buf bytes.Buffer
 89→	buf.WriteString(strings.TrimRight(basic, "\n"))
 90→	_ = memoriesTmpl.Execute(&buf, memories)
 91→
 92→	if skills := FormatSkillsForPrompt(LoadSkills(annaHome, workspace, workDir)); skills != "" {
 93→		buf.WriteString("\n")
 94→		buf.WriteString(skills)
 95→	}
 96→
 97→	if ctxFiles := loadProjectContextFiles(workDir); len(ctxFiles) > 0 {
 98→		buf.WriteString("\n\n# Project Context\n\n")
 99→		buf.WriteString("Project-specific instructions and guidelines:\n\n")
100→		for _, f := range ctxFiles {
101→			buf.WriteString("## " + f.Path + "\n\n")
102→			buf.WriteString(strings.TrimRight(f.Content, "\n"))
103→			buf.WriteString("\n\n")
104→		}
105→	}
106→
107→	return buf.String()
108→}
109→
110→// readFileIfExists reads a file from dir with case-insensitive matching.
111→// Returns the trimmed content, or empty string if not found.
112→func readFileIfExists(dir, name string) string {
113→	path := resolveFile(dir, name)
114→	if path == "" {
115→		return ""
116→	}
117→	data, err := os.ReadFile(path)
118→	if err != nil {
119→		return ""
120→	}
121→	return strings.TrimSpace(string(data))
122→}
123→
124→// loadProjectContextFiles walks from cwd up to the filesystem root,
125→// collecting AGENTS.md files from each directory (case-insensitive).
126→// Files are returned in root-to-leaf order (ancestors first).
127→func loadProjectContextFiles(cwd string) []contextFile {
128→	if cwd == "" {
129→		return nil
130→	}
131→
132→	absDir, err := filepath.Abs(cwd)
133→	if err != nil {
134→		return nil
135→	}
136→
137→	var files []contextFile
138→	seen := map[string]bool{}
139→
140→	for {
141→		if path := resolveFile(absDir, "AGENTS.md"); path != "" {
142→			if !seen[path] {
143→				seen[path] = true
144→				if data, err := os.ReadFile(path); err == nil {
145→					files = append(files, contextFile{Path: path, Content: string(data)})
146→				}
147→			}
148→		}
149→
150→		parent := filepath.Dir(absDir)
151→		if parent == absDir {
152→			break
153→		}
154→		absDir = parent
155→	}
156→
157→	// Reverse so ancestors come first (root → leaf).
158→	for i, j := 0, len(files)-1; i < j; i, j = i+1, j-1 {
159→		files[i], files[j] = files[j], files[i]
160→	}
161→
162→	return files
163→}
164→
165→// resolveFile finds a file in dir with case-insensitive matching.
166→// Returns the full path if found, empty string otherwise.
167→func resolveFile(dir, name string) string {
168→	exact := filepath.Join(dir, name)
169→	if _, err := os.Stat(exact); err == nil {
170→		return exact
171→	}
172→	entries, err := os.ReadDir(dir)
173→	if err != nil {
174→		return ""
175→	}
176→	target := strings.ToLower(name)
177→	for _, e := range entries {
178→		if strings.ToLower(e.Name()) == target {
179→			return filepath.Join(dir, e.Name())
180→		}
181→	}
182→	return ""
183→}
184→
185→func fallback(value, def string) string {
186→	if value != "" {
187→		return value
188→	}
189→	return strings.TrimSpace(def)
190→}
