  1→/**
  2→ * Agent Coordinator
  3→ *
  4→ * Always-on service that listens to observation LIVE SELECT events,
  5→ * routes them to semantically matched agents via KNN vector search
  6→ * on agent session description embeddings, and invokes matched agents.
  7→ *
  8→ * Pure core: filterAboveThreshold, extractObservationEmbedding, isObservationCreate
  9→ * Stateful shell: createAgentCoordinator (wires LiveSelectManager, SurrealDB, LoopDampener)
 10→ *
 11→ * Uses two-step KNN pattern per CLAUDE.md SurrealDB KNN + WHERE bug:
 12→ *   Step 1: KNN candidates from agent_session via HNSW index
 13→ *   Step 2: filter by workspace + active session status
 14→ *
 15→ * Step: 03-02 (Graph-Reactive Coordination)
 16→ */
 17→import { RecordId, type Surreal } from "surrealdb";
 18→import type { LiveSelectManager, LiveSelectEvent } from "./live-select-manager";
 19→import type { LoopDampener, DampenerEvent } from "./loop-dampener";
 20→
 21→// ---------------------------------------------------------------------------
 22→// Domain Types
 23→// ---------------------------------------------------------------------------
 24→
 25→/** A matched agent with similarity score and session info. */
 26→export type AgentMatch = {
 27→  agentId: string;
 28→  sessionId: string;
 29→  workspaceId: string;
 30→  similarity: number;
 31→  observationId: string;
 32→  observationText: string;
 33→};
 34→
 35→/** Callback invoked when the coordinator matches an agent to an observation. */
 36→export type OnAgentMatch = (match: AgentMatch) => void;
 37→
 38→/** Configuration for the coordinator's KNN search. */
 39→export type CoordinatorConfig = {
 40→  /** Minimum cosine similarity to consider a match (0-1). */
 41→  similarityThreshold: number;
 42→  /** Maximum number of KNN candidates to retrieve. */
 43→  knnCandidates: number;
 44→};
 45→
 46→/** Dependencies injected into the coordinator. */
 47→export type AgentCoordinatorDeps = {
 48→  surreal: Surreal;
 49→  liveSelectManager: LiveSelectManager;
 50→  loopDampener: LoopDampener;
 51→  onAgentMatch: OnAgentMatch;
 52→  config?: Partial<CoordinatorConfig>;
 53→};
 54→
 55→export type AgentCoordinator = {
 56→  start: () => void;
 57→  stop: () => void;
 58→};
 59→
 60→// ---------------------------------------------------------------------------
 61→// Pure Functions
 62→// ---------------------------------------------------------------------------
 63→
 64→const DEFAULT_CONFIG: CoordinatorConfig = {
 65→  similarityThreshold: 0.3,
 66→  knnCandidates: 20,
 67→};
 68→
 69→/**
 70→ * Filters KNN candidates above the similarity threshold.
 71→ * Returns only matches where similarity >= threshold.
 72→ */
 73→export function filterAboveThreshold(
 74→  candidates: ReadonlyArray<{ sessionId: string; similarity: number }>,
 75→  threshold: number,
 76→): Array<{ sessionId: string; similarity: number }> {
 77→  return candidates.filter((c) => c.similarity >= threshold);
 78→}
 79→
 80→/**
 81→ * Extracts the embedding array from an observation event value.
 82→ * Returns undefined if no embedding is present.
 83→ */
 84→export function extractObservationEmbedding(
 85→  value: Record<string, unknown>,
 86→): number[] | undefined {
 87→  const embedding = value.embedding;
 88→  if (Array.isArray(embedding) && embedding.length > 0) {
 89→    return embedding as number[];
 90→  }
 91→  return undefined;
 92→}
 93→
 94→/**
 95→ * Extracts the workspace ID string from an event value.
 96→ * Handles both RecordId objects and "workspace:id" strings.
 97→ */
 98→export function extractWorkspaceId(
 99→  value: Record<string, unknown>,
100→): string | undefined {
101→  const workspace = value.workspace;
102→  if (!workspace) return undefined;
103→
104→  if (workspace instanceof RecordId) {
105→    return workspace.id as string;
106→  }
107→
108→  if (typeof workspace === "string") {
109→    const parts = workspace.split(":");
110→    if (parts.length >= 2) {
111→      return parts.slice(1).join(":");
112→    }
113→  }
114→
115→  return undefined;
116→}
117→
118→/**
119→ * Determines whether a LiveSelectEvent is an observation CREATE event.
120→ */
121→export function isObservationCreate(event: LiveSelectEvent): boolean {
122→  return event.table === "observation" && event.action === "CREATE";
123→}
124→
125→/**
126→ * Builds a dampener event from an observation LiveSelectEvent.
127→ * Keys on the target entity (from observes edge) to detect rapid-fire
128→ * observations targeting the same entity from the same source.
129→ */
130→export function buildDampenerEvent(
131→  workspaceId: string,
132→  entityId: string,
133→  sourceAgent: string,
134→): DampenerEvent {
135→  return {
136→    workspaceId,
137→    entityId,
138→    sourceAgent,
139→  };
140→}
141→
142→// ---------------------------------------------------------------------------
143→// KNN Query (Side-Effect Boundary)
144→// ---------------------------------------------------------------------------
145→
146→type KnnCandidate = {
147→  sessionId: string;
148→  similarity: number;
149→  agent: string;
150→};
151→
152→/**
153→ * Runs the two-step KNN search on agent_session using sequential queries.
154→ *
155→ * Step 1: KNN on agent_session.description_embedding (HNSW index only, no WHERE)
156→ * Step 2: Filter by workspace + active status (B-tree index)
157→ *
158→ * This avoids the SurrealDB v3.0 KNN + WHERE index conflict bug by
159→ * separating HNSW and B-tree index usage into two queries.
160→ */
161→async function findMatchingAgents(
162→  surreal: Surreal,
163→  observationEmbedding: number[],
164→  workspaceId: string,
165→  config: CoordinatorConfig,
166→): Promise<KnnCandidate[]> {
167→  const workspaceRecord = new RecordId("workspace", workspaceId);
168→
169→  // Step 1: KNN candidates from agent_session table (HNSW index, no WHERE filter)
