293→/**
294→ * Creates the Agent Coordinator that listens to observation events
295→ * and routes them to semantically matched agents.
296→ *
297→ * Dependencies injected: surreal, liveSelectManager, loopDampener, onAgentMatch.
298→ */
299→export function createAgentCoordinator(deps: AgentCoordinatorDeps): AgentCoordinator {
300→  const { surreal, liveSelectManager, loopDampener, onAgentMatch } = deps;
301→  const config: CoordinatorConfig = {
302→    ...DEFAULT_CONFIG,
303→    ...deps.config,
304→  };
305→
306→  let unsubscribe: (() => void) | undefined;
307→
308→  function handleObservationEvent(event: LiveSelectEvent): void {
309→    if (!isObservationCreate(event)) return;
310→
311→    const workspaceId = extractWorkspaceId(event.value);
312→    if (!workspaceId) return;
313→
314→    const observationId = event.recordId;
315→    const sourceAgent = (event.value.source_agent as string) ?? "unknown";
316→    const observationText = (event.value.text as string) ?? "";
317→    const embedding = extractObservationEmbedding(event.value);
318→
319→    // Resolve target entity for dampener keying, then check dampener + route
320→    resolveObservationTarget(surreal, observationId)
321→      .then((targetEntity) => {
322→        const dampenerEntityKey = targetEntity ?? observationId;
323→        const dampenerEvent = buildDampenerEvent(workspaceId, dampenerEntityKey, sourceAgent);
324→        const dampenerResult = loopDampener.record(dampenerEvent);
325→
326→        if (dampenerResult.dampened) {
327→          // Create meta-observation in the graph (fire-and-forget)
328→          createDampeningMetaObservation(
329→            surreal,
330→            workspaceId,
331→            dampenerEntityKey,
332→            sourceAgent,
333→          ).catch((err) => {
334→            console.error(
335→              `[AgentCoordinator] Failed to create dampening meta-observation:`,
336→              err instanceof Error ? err.message : String(err),
337→            );
338→          });
339→          return;
340→        }
341→
342→        // Only run KNN routing if observation has an embedding
343→        if (!embedding) return;
344→
345→        routeObservation(
346→          surreal,
347→          embedding,
348→          workspaceId,
349→          observationId,
350→          observationText,
351→          config,
352→          onAgentMatch,
353→        ).catch((err) => {
354→          console.error(
355→            `[AgentCoordinator] Failed to route observation ${observationId}:`,
356→            err instanceof Error ? err.message : String(err),
357→          );
358→        });
359→      })
360→      .catch((err) => {
361→        console.error(
362→          `[AgentCoordinator] Failed to resolve target for observation ${observationId}:`,
363→          err instanceof Error ? err.message : String(err),
364→        );
365→      });
366→  }
367→
368→  async function routeObservation(
369→    db: Surreal,
370→    embedding: number[],
371→    workspaceId: string,
372→    observationId: string,
373→    observationText: string,
374→    cfg: CoordinatorConfig,
375→    callback: OnAgentMatch,
376→  ): Promise<void> {
377→    const matches = await findMatchingAgents(db, embedding, workspaceId, cfg);
378→
379→    for (const match of matches) {
380→      // Update session last_request_at to signal the agent was notified
381→      const sessionRecord = new RecordId("agent_session", match.sessionId);
382→      await db.query(
383→        `UPDATE $sess SET last_request_at = time::now();`,
384→        { sess: sessionRecord },
385→      ).catch(() => undefined);
386→
387→      callback({
388→        agentId: match.agent,
389→        sessionId: match.sessionId,
390→        workspaceId,
391→        similarity: match.similarity,
392→        observationId,
393→        observationText,
394→      });
395→    }
396→  }
397→
398→  function start(): void {
399→    unsubscribe = liveSelectManager.onAnyEvent(handleObservationEvent);
400→  }
401→
402→  function stop(): void {
403→    unsubscribe?.();
404→    unsubscribe = undefined;
405→  }
406→
407→  return { start, stop };
408→}
