 1→/**
 2→ * System prompt assembly for agent sessions.
 3→ *
 4→ * Uses the template registry (session-templates.ts) for the core prompt
 5→ * building blocks. Dynamic sections (identity, repo context, CLAUDE.md,
 6→ * TOOLS.md) and conditional sections (agent_fs, services, artifacts) are
 7→ * still assembled here based on runtime state.
 8→ */
 9→
10→import { resolveTemplate } from "./resolver";
11→
12→// Side-effect import: register all system + session templates
13→import "./session-templates";
14→
15→/** Max characters per individual injected section before truncation */
16→const BOOTSTRAP_MAX_CHARS = 20_000;
17→
18→/** Max total characters across all injected sections combined */
19→const BOOTSTRAP_TOTAL_MAX_CHARS = 150_000;
20→
21→/** Truncation notice appended when a section is cut */
22→const truncationNotice = (file: string) =>
23→  `\n\n[...truncated, see /workspace/${file} for full content]\n`;
24→
25→export type BasePromptArgs = {
26→  role: string;
27→  agentId: string;
28→  swarmUrl: string;
29→  capabilities?: string[];
30→  name?: string;
31→  description?: string;
32→  soulMd?: string;
33→  identityMd?: string;
34→  toolsMd?: string;
35→  claudeMd?: string;
36→  repoContext?: {
37→    claudeMd?: string | null;
38→    clonePath: string;
39→    warning?: string | null;
40→  };
41→};
42→
43→export const getBasePrompt = (args: BasePromptArgs): string => {
44→  const { role, agentId, swarmUrl } = args;
45→
46→  const vars: Record<string, string> = { role, agentId, swarmUrl };
47→
48→  // Resolve the composite session template (lead or worker)
49→  const compositeEventType = role === "lead" ? "system.session.lead" : "system.session.worker";
50→  const compositeResult = resolveTemplate(compositeEventType, vars);
51→  let prompt = compositeResult.text;
52→
53→  // Inject agent identity (soul + identity + name/description) if available
54→  if (args.soulMd || args.identityMd || args.name) {
55→    prompt += "\n\n## Your Identity\n\n";
56→    if (args.name) {
57→      prompt += `**Name:** ${args.name}\n`;
58→      if (args.description) {
59→        prompt += `**Description:** ${args.description}\n`;
60→      }

 60→      }
 61→      prompt += "\n";
 62→    }
 63→    if (args.soulMd) {
 64→      prompt += `${args.soulMd}\n`;
 65→    }
 66→    if (args.identityMd) {
 67→      prompt += `${args.identityMd}\n`;
 68→    }
 69→  }
 70→
 71→  // Repo context (protected, never truncated)
 72→  if (args.repoContext) {
 73→    prompt += "\n\n## Repository Context\n\n";
 74→
 75→    if (args.repoContext.warning) {
 76→      prompt += `WARNING: ${args.repoContext.warning}\n\n`;
 77→    }
 78→
 79→    if (args.repoContext.claudeMd) {
 80→      prompt += `The following CLAUDE.md is from the repository cloned at \`${args.repoContext.clonePath}\`. `;
 81→      prompt += `**IMPORTANT: These instructions apply ONLY when working within the \`${args.repoContext.clonePath}\` directory.** `;
 82→      prompt += `Do NOT apply these rules to files outside that directory.\n\n`;
 83→      prompt += `${args.repoContext.claudeMd}\n`;
 84→    } else if (!args.repoContext.warning) {
 85→      prompt += `Repository is cloned at \`${args.repoContext.clonePath}\` but has no CLAUDE.md file.\n`;
 86→    }
 87→  }
 88→
 89→  // Build conditional suffix (sections that depend on runtime env/capabilities)
 90→  let conditionalSuffix = "";
 91→
 92→  // Conditionally include agent-fs instructions when available
 93→  if (process.env.AGENT_FS_API_URL) {
 94→    const sharedOrgId = process.env.AGENT_FS_SHARED_ORG_ID || "YOUR_SHARED_ORG_ID";
 95→    const agentFsResult = resolveTemplate("system.agent.agent_fs", {
 96→      agentId,
 97→      sharedOrgId,
 98→    });
 99→    conditionalSuffix += agentFsResult.text;
100→  }
101→
102→  if (!args.capabilities || args.capabilities.includes("services")) {
103→    const servicesResult = resolveTemplate("system.agent.services", {
104→      agentId,
105→      swarmUrl,
106→    });
107→    conditionalSuffix += servicesResult.text;
108→  }
109→
110→  if (!args.capabilities || args.capabilities.includes("artifacts")) {
111→    const artifactsResult = resolveTemplate("system.agent.artifacts", {});
112→    conditionalSuffix += artifactsResult.text;
113→  }
114→
115→  if (args.capabilities) {
116→    conditionalSuffix += `
117→### Capabilities enabled for this agent:
118→
119→- ${args.capabilities.join("\n- ")}
120→`;
121→  }
122→
123→  // Inject truncatable sections with per-section and total character caps
124→  // Priority: agent CLAUDE.md > tools (tools cut first when over total budget)
125→  const protectedLength = prompt.length + conditionalSuffix.length;
126→  const totalBudget = Math.max(0, BOOTSTRAP_TOTAL_MAX_CHARS - protectedLength);
127→  let totalUsed = 0;
128→
129→  // Agent CLAUDE.md (higher priority — injected first)
130→  if (args.claudeMd) {
131→    const perSectionBudget = Math.min(BOOTSTRAP_MAX_CHARS, totalBudget - totalUsed);
132→    const section = truncateSection(
133→      args.claudeMd,
134→      "## Agent Instructions",
135→      "CLAUDE.md",
136→      perSectionBudget,
137→    );
138→    prompt += section;
139→    totalUsed += section.length;

