595→// ---------------------------------------------------------------------------
596→// acceptOrchestratorSession
597→// ---------------------------------------------------------------------------
598→
599→type AcceptSessionInput = {
600→  surreal: Surreal;
601→  sessionId: string;
602→  summary: string;
603→  endAgentSession: (input: {
604→    surreal: Surreal;
605→    workspaceRecord: RecordId<"workspace", string>;
606→    sessionId: string;
607→    summary: string;
608→  }) => Promise<{ session_id: string; ended: boolean }>;
609→};
610→
611→export async function acceptOrchestratorSession(
612→  input: AcceptSessionInput,
613→): Promise<AcceptSessionResult> {
614→  const lookup = await lookupSession(input.surreal, input.sessionId);
615→  if (!lookup.ok) {
616→    return { ok: false, error: lookup.error };
617→  }
618→  const { session, record: sessionRecord, status } = lookup;
619→
620→  if (!ACCEPTABLE_STATUSES.has(status)) {
621→    return { ok: false, error: sessionStateConflict(input.sessionId, status, "accept") };
622→  }
623→
624→  const workspaceRecord = requireWorkspace(session, input.sessionId);
625→
626→  // 1. Update orchestrator_status to completed
627→  await input.surreal.update(sessionRecord).merge({
628→    orchestrator_status: "completed" as OrchestratorStatus,
629→  });
630→
631→  // 2. (handle registry eliminated — no cleanup needed)
632→
633→  // 3. End the agent session
634→  await input.endAgentSession({
635→    surreal: input.surreal,
636→    workspaceRecord,
637→    sessionId: input.sessionId,
638→    summary: input.summary,
639→  });
640→
641→  return {
642→    ok: true,
643→    value: {
644→      accepted: true,
645→      sessionId: input.sessionId,
646→    },
647→  };
648→}
