  1→//! Import workspace personality files from OpenClaw.
  2→//!
  3→//! Copies `SOUL.md`, `IDENTITY.md`, `USER.md`, `TOOLS.md`, `AGENTS.md`,
  4→//! `HEARTBEAT.md`, and `BOOT.md` from the OpenClaw workspace directory to the
  5→//! Moltis data directory, preserving any user-customized files at the destination.
  6→
  7→use std::path::Path;
  8→
  9→use tracing::{debug, warn};
 10→
 11→use crate::{
 12→    detect::OpenClawDetection,
 13→    report::{CategoryReport, ImportCategory, ImportStatus},
 14→};
 15→
 16→/// The set of workspace personality files to import.
 17→pub const WORKSPACE_FILE_NAMES: &[&str] = &[
 18→    "SOUL.md",
 19→    "IDENTITY.md",
 20→    "USER.md",
 21→    "TOOLS.md",
 22→    "AGENTS.md",
 23→    "HEARTBEAT.md",
 24→    "BOOT.md",
 25→];
 26→
 27→/// Import workspace personality files from the default agent's workspace.
 28→pub fn import_workspace_files(
 29→    detection: &OpenClawDetection,
 30→    dest_data_dir: &Path,
 31→) -> CategoryReport {
 32→    import_agent_workspace_files(&detection.workspace_dir, dest_data_dir)
 33→}
 34→
 35→/// Import workspace files for a specific agent from a source workspace
 36→/// to a destination directory.
 37→///
 38→/// This is the core logic, usable for both the default agent
 39→/// (via [`import_workspace_files`]) and non-default agents with per-agent
 40→/// workspaces.
 41→pub fn import_agent_workspace_files(source_workspace: &Path, dest_dir: &Path) -> CategoryReport {
 42→    let mut imported = 0;
 43→    let mut skipped = 0;
 44→    let mut errors = Vec::new();
 45→
 46→    for file_name in WORKSPACE_FILE_NAMES {
 47→        let src = source_workspace.join(file_name);
 48→        if !src.is_file() {
 49→            continue;
 50→        }
 51→
 52→        let dest = dest_dir.join(file_name);
 53→
 54→        match import_single_file(&src, &dest, file_name) {
 55→            Ok(FileImportResult::Created) => {
 56→                debug!(file = *file_name, "imported workspace file (new)");
 57→                imported += 1;
 58→            },
 59→            Ok(FileImportResult::Replaced) => {
 60→                debug!(
 61→                    file = *file_name,
 62→                    "replaced default workspace file with imported content"
 63→                );
 64→                imported += 1;
 65→            },
 66→            Ok(FileImportResult::Skipped) => {
 67→                debug!(file = *file_name, "workspace file already exists, skipping");
 68→                skipped += 1;
 69→            },
 70→            Err(e) => {
 71→                warn!(file = *file_name, error = %e, "failed to import workspace file");
 72→                errors.push(format!("failed to import {file_name}: {e}"));
 73→            },
 74→        }
 75→    }
 76→
 77→    let status = if !errors.is_empty() && imported > 0 {
 78→        ImportStatus::Partial
 79→    } else if !errors.is_empty() {
 80→        ImportStatus::Failed
 81→    } else if imported == 0 {
 82→        ImportStatus::Skipped
 83→    } else {
 84→        ImportStatus::Success
 85→    };
 86→
 87→    CategoryReport {
 88→        category: ImportCategory::WorkspaceFiles,
 89→        status,
 90→        items_imported: imported,
 91→        items_updated: 0,
 92→        items_skipped: skipped,
 93→        warnings: Vec::new(),
 94→        errors,
 95→    }
 96→}
 97→
 98→enum FileImportResult {
 99→    Created,
100→    Replaced,
101→    Skipped,
102→}
103→
104→fn import_single_file(
105→    src: &Path,
106→    dest: &Path,
107→    file_name: &str,
108→) -> crate::error::Result<FileImportResult> {
109→    let src_content = std::fs::read_to_string(src)?;
110→    if src_content.trim().is_empty() {
111→        return Ok(FileImportResult::Skipped);
112→    }
113→
114→    // Destination doesn't exist — create it.
115→    if !dest.exists() {
116→        if let Some(parent) = dest.parent() {
117→            std::fs::create_dir_all(parent)?;
118→        }
119→        std::fs::write(dest, &src_content)?;
120→        return Ok(FileImportResult::Created);
121→    }
122→
123→    let dest_content = std::fs::read_to_string(dest)?;
124→    let dest_trimmed = dest_content.trim();
125→
126→    // Non-empty file that user may have customized — skip.
127→    if !dest_trimmed.is_empty() && !is_default_content(file_name, dest_trimmed) {
128→        return Ok(FileImportResult::Skipped);
129→    }
130→
131→    // Empty file or contains only the auto-seeded default — replace.
132→    std::fs::write(dest, &src_content)?;
133→    Ok(FileImportResult::Replaced)
134→}
135→
136→/// Check whether the destination file contains only the auto-seeded default.
137→///
138→/// Currently only `SOUL.md` has auto-seeding via `DEFAULT_SOUL` in
139→/// `moltis_config::loader`. For other files the function returns `false`
140→/// (they are only overwritten if empty).
141→fn is_default_content(file_name: &str, content: &str) -> bool {
142→    if file_name == "SOUL.md" {
143→        return content == moltis_config::DEFAULT_SOUL.trim();
144→    }
145→    false
146→}
