311→/// Format a tool schema in compact human-readable form for text-mode prompts.
312→///
313→/// Output: `### tool_name\ndescription\nParams: param1 (type, required), param2 (type)\n`
314→///
315→/// This is much shorter than dumping full JSON schema, saving ~60% context tokens.
316→fn format_compact_tool_schema(schema: &serde_json::Value) -> String {
317→    let name = schema["name"].as_str().unwrap_or("unknown");
318→    let desc = schema["description"].as_str().unwrap_or("");
319→    let params = &schema["parameters"];
320→
321→    let mut out = format!("### {name}\n{desc}\n");
322→
323→    if let Some(properties) = params.get("properties").and_then(|v| v.as_object()) {
324→        let required: Vec<&str> = params
325→            .get("required")
326→            .and_then(|v| v.as_array())
327→            .map(|arr| arr.iter().filter_map(|v| v.as_str()).collect())
328→            .unwrap_or_default();
329→
330→        let mut param_parts: Vec<String> = Vec::with_capacity(properties.len());
331→        for (param_name, param_schema) in properties {
332→            let type_str = param_schema
333→                .get("type")
334→                .and_then(|v| v.as_str())
335→                .unwrap_or("any");
336→            if required.contains(&param_name.as_str()) {
337→                param_parts.push(format!("{param_name} ({type_str}, required)"));
338→            } else {
339→                param_parts.push(format!("{param_name} ({type_str})"));
340→            }
341→        }
342→
343→        if !param_parts.is_empty() {
344→            out.push_str("Params: ");
345→            out.push_str(&param_parts.join(", "));
346→            out.push('\n');
347→        }
348→    }
349→    out.push('\n');
350→    out
351→}
