728→                    file = label,
729→                    original_chars = status.original_chars,
730→                    limit = status.limit_chars,
731→                    "workspace file truncated for prompt size"
732→                );
733→            }
734→            statuses.push(status);
735→            prompt.push_str("\n\n");
736→        }
737→    }
738→
739→    statuses
