 933→}
 934→
 935→pub(crate) fn should_redirect_from_onboarding(onboarded: bool, auth_setup_pending: bool) -> bool {
 936→    onboarded && !auth_setup_pending
 937→}
 938→
 939→fn is_onboarding_path(path: &str) -> bool {
 940→    path == "/onboarding" || path == "/onboarding/"
 941→}
